-- Vorrats-Aufgaben (rollend-8) in bestehende Flüge einfügen: 156 Aufgaben, 10 Einheiten, mit form und zaehlt (FT-S). Ein Aufruf, eine Transaktion.
select set_config('lock_timeout', '3s', true), set_config('statement_timeout', '60s', true);
do $einspielen$
declare e record; n int; vorher int; gesamt int := 0; fehler text[] := '{}';
begin
  if (select count(*) from pg_attribute where attrelid = 'schule.aufgabe'::regclass and attname in ('form', 'zaehlt') and not attisdropped) <> 2
     or position('x->>''form''' in pg_get_functiondef('schule.aufgaben_einfuegen(bigint, jsonb)'::regprocedure)) = 0 then
    raise exception 'Vorrats-Aufgaben: erst FT-S einspielen (Spalten form/zaehlt, aufgaben_einfuegen)'; end if;
  for e in select * from (values
    (2, 'finanzen.zinsen', 636, 24, $auf$[{"l": "begriffe", "t": "begriffe", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Auf einem Sparkonto liegen 1 500 €. Die Bank zahlt 2 % Zinsen im Jahr. 1 % des Kapitals sind ① €. Die Zinsen für ein Jahr sind ② €. Mit den Zinsen stehen nach dem Jahr ③ € auf dem Konto.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [15, 30, 1530]}, "h": "Erst ein Prozent, dann das Vielfache.", "w": "1 % von 1 500 € sind 15 €. 2 % sind 2 · 15 € = 30 €. Die Zinsen kommen zum Kapital dazu: 1 500 € + 30 € = 1 530 €.", "form": "lueckenweg", "zaehlt": "nein", "r": 8637}, {"l": "begriffe", "t": "begriffe", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Ein Konto wird kurz so beschrieben: K = 800 €, p = 5 %, Z = 40 € (Z sind die Zinsen für ein Jahr). Welcher Satz sagt dasselbe?"}, "a": ["Die Bank zahlt 40 % Zinsen auf 800 €.", "Für 800 € bekommt man im Jahr 40 € Zinsen.", "Die Bank zahlt im Jahr 5 € Zinsen.", "Nach einem Jahr stehen 840 % auf dem Konto."], "o": {"index": 1}, "h": "Lies nach, welche Größe in Euro steht und welche in Prozent.", "w": "K = 800 € ist das Kapital, p = 5 % der Zinssatz, Z = 40 € der Zinsbetrag für ein Jahr. 5 % von 800 € sind wirklich 40 €.", "form": "bruecke", "zaehlt": "ja", "r": 8638}, {"l": "begriffe", "t": "begriffe", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Kind erklärt ein Konto mit K = 2 400 € und p = 3 %. Zeile 1: Das Kapital ist der Betrag auf dem Konto, also 2 400 €. Zeile 2: Der Zinssatz 3 % bedeutet, dass es im Jahr 3 € Zinsen gibt. Zeile 3: Die Zinsen für ein Jahr sind deshalb 3 €. In welcher Zeile steckt der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Prüfe, ob 3 % von 2 400 € wirklich nur 3 € sind.", "w": "Zeile 1 stimmt. Zeile 2 ist falsch: 3 % heißt 3 € für je 100 € Kapital. In 2 400 € stecken 24 Hunderter, also 24 · 3 € = 72 €. Zeile 3 folgt richtig aus Zeile 2, übernimmt aber deren Fehler.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 8639}, {"l": "rollen", "t": "rollen", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Eine Familie hat einen Kredit über 2 000 € zu 6 % und ein Sparkonto mit 500 € zu 1 %. Gefragt ist nur, wie viel Zinsen die Familie im Jahr für den Kredit an die Bank zahlen muss. Welche Rechnung passt?"}, "a": ["2 000 € · 6 : 100 = 120 €", "2 000 € · 6 : 100 − 500 € · 1 : 100 = 115 €", "500 € · 1 : 100 = 5 €", "2 000 € · 6 : 100 + 500 € · 1 : 100 = 125 €"], "o": {"index": 0}, "h": "Zinsen zahlt man nur für geliehenes Geld.", "w": "Für den Kredit zahlt die Familie 2 000 € · 6 : 100 = 120 €. Die 5 € vom Sparkonto bekommt sie, sie zahlt sie nicht. Gefragt ist nur das Gezahlte: 120 €.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 8640}, {"l": "rollen", "t": "rollen", "p": "uebung", "s": 2, "g": "umkehr", "y": "auswahl", "f": {"text": "Am Ende eines Jahres sind einer Person 18 € Zinsen gutgeschrieben worden. Sie hat die Zinsen also bekommen. Welche Lage passt dazu?"}, "a": ["Sie hat Geld verzinst angelegt.", "Sie hat einen Kredit aufgenommen.", "Sie hat Geld in einer Spardose.", "Sie hat Geld verliehen, ohne Zinsen zu verlangen."], "o": {"index": 0}, "h": "Wer zahlt hier die Zinsen, und wer bekommt sie?", "w": "Gutgeschriebene Zinsen bekommt man. Das passt zum verzinsten Anlegen. Bei einem Kredit zahlt man Zinsen, in der Spardose und beim zinslosen Verleihen gibt es keine.", "form": "umkehren", "zaehlt": "ja", "r": 8641}, {"l": "rollen", "t": "rollen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Kind sagt: Zeile 1: Wer einen Kredit hat, zahlt Zinsen. Zeile 2: Wer Geld auf einem Sparkonto hat, bekommt Zinsen. Zeile 3: Wer Geld in einer Spardose hat, bekommt auch Zinsen. In welcher Zeile steckt der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Frage bei jeder Zeile: Wer benutzt das Geld, und wer bezahlt dafür?", "w": "Zeile 1 und 2 stimmen. Das Geld in der Spardose benutzt niemand, deshalb gibt es dafür keine Zinsen.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 8642}, {"l": "jahreszinsen", "t": "jahreszinsen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Kapital von 2 500 € wird mit 3 % verzinst. 1 % des Kapitals sind ① €. Die Zinsen für ein Jahr sind ② €. Sie werden jedes Jahr abgehoben, das Kapital bleibt gleich. Nach zwei Jahren hat die Bank insgesamt ③ € Zinsen gezahlt.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [25, 75, 150]}, "h": "Erst ein Prozent, dann das Vielfache.", "w": "1 % von 2 500 € sind 25 €. 3 % sind 3 · 25 € = 75 €. Weil die Zinsen abgehoben werden, kommt jedes Jahr derselbe Betrag: 2 · 75 € = 150 €.", "form": "lueckenweg", "zaehlt": "nein", "r": 8643}, {"l": "jahreszinsen", "t": "jahreszinsen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Kapital von 1 200 € wird mit 6 % verzinst. Weg A: 1 % sind 12 €, davon nimmst du 6-mal. Weg B: 1 200 · 6 = 7 200, dann durch 100 teilen. Wie hoch sind die Jahreszinsen?"}, "o": {"wert": 72, "einheit": "€"}, "h": "Beide Wege müssen denselben Betrag ergeben.", "w": "Weg A: 6 · 12 € = 72 €. Weg B: 7 200 : 100 = 72 €. Die Jahreszinsen sind 72 €.", "form": "zwei_wege", "zaehlt": "ja", "r": 8644}, {"l": "jahreszinsen", "t": "jahreszinsen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Kind rechnet die Jahreszinsen für 900 € bei 4 % und danach den Kontostand. Zeile 1: 1 % von 900 € sind 90 €. Zeile 2: 4 % sind 4 · 90 € = 360 €. Zeile 3: Nach einem Jahr stehen 900 € + 360 € = 1 260 € auf dem Konto. In welcher Zeile steckt der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Rechne Zeile 1 selbst nach.", "w": "Zeile 1 ist falsch: 1 % von 900 € sind 900 € : 100 = 9 €. Die Zeilen 2 und 3 rechnen mit dem falschen Wert richtig weiter. Mit 9 € ergeben sich 36 € Zinsen und 936 € auf dem Konto.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 8645}, {"l": "jahreszinsen_komma", "t": "jahreszinsen_komma", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Kapital von 1 600 € wird mit 2,5 % verzinst. 1 % des Kapitals sind ① €. Die Hälfte davon ist der Betrag für 0,5 %: ② €. Die Zinsen für ein Jahr sind ③ €.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [16, 8, 40]}, "h": "2,5 % sind 2 % und noch 0,5 % dazu.", "w": "1 % von 1 600 € sind 16 €, 0,5 % sind 8 €. 2,5 % sind 2 · 16 € + 8 € = 40 €.", "form": "lueckenweg", "zaehlt": "nein", "r": 8646}, {"l": "jahreszinsen_komma", "t": "jahreszinsen_komma", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Verein legt 4 000 € für ein Jahr zu 1,5 % an. Mit den Zinsen sollen Trikots bezahlt werden, ein Trikot kostet 20 €. Wie viele ganze Trikots kann der Verein davon bezahlen?"}, "o": {"wert": 3, "einheit": "Trikots"}, "h": "Rechne zuerst die Jahreszinsen, dann teile durch den Preis.", "w": "1 % von 4 000 € sind 40 €. 1,5 % sind 40 € + 20 € = 60 €. 60 € : 20 € = 3 Trikots.", "form": "anwenden", "zaehlt": "ja", "r": 8647}, {"l": "jahreszinsen_komma", "t": "jahreszinsen_komma", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Kind rechnet 3,5 % von 1 400 €. Zeile 1: 1 % von 1 400 € sind 14 €. Zeile 2: Jetzt mit 0,035 malnehmen: 14 € · 0,035 = 0,49 €. Zeile 3: 0,49 € sind weniger als ein Euro. In welcher Zeile steckt der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Nach dem 1-%-Schritt nimmst du mit der Prozentzahl mal.", "w": "Zeile 1 stimmt. Falsch ist Zeile 2: Nach dem 1-%-Schritt nimmst du mit 3,5 mal, also 14 € · 3,5 = 49 €. Zeile 3 folgt richtig aus Zeile 2 (0,49 € sind wirklich weniger als ein Euro), übernimmt aber den Fehler.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 8648}, {"l": "zinssatz", "t": "zinssatz", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Für ein Kapital von 600 € gibt es im Jahr 24 € Zinsen. 1 % des Kapitals sind ① €. Der Zinssatz ist ② %. Bei diesem Zinssatz bringen 2 500 € im Jahr ③ € Zinsen.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [6, 4, 100]}, "h": "Wie oft passt 1 % in die Zinsen?", "w": "1 % von 600 € sind 6 €. In 24 € stecken 24 : 6 = 4 solche Schritte, der Zinssatz ist 4 %. Für 2 500 € sind 1 % genau 25 €, also 4 · 25 € = 100 €.", "form": "lueckenweg", "zaehlt": "nein", "r": 8649}, {"l": "zinssatz", "t": "zinssatz", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Kapital von 750 € bringt im Jahr 30 € Zinsen. Weg A: 1 % sind 7,50 €, und in 30 € stecken 30 : 7,50 Schritte. Weg B: 30 : 750 = 0,04, das mal 100. Wie hoch ist der Zinssatz in Prozent?"}, "o": {"wert": 4, "einheit": "%"}, "h": "Beide Wege führen zur gleichen Prozentzahl.", "w": "Weg A: 30 : 7,50 = 4. Weg B: 0,04 · 100 = 4. Der Zinssatz ist 4 %.", "form": "zwei_wege", "zaehlt": "ja", "r": 8650}, {"l": "zinssatz", "t": "zinssatz", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Kind sucht den Zinssatz für 800 € Kapital und 32 € Zinsen. Zeile 1: Der Zinssatz ist Zinsen durch Kapital, mal 100. Zeile 2: Also ist der Zinssatz 800 : 32 · 100 = 2 500 %. Zeile 3: 2 500 % wären für ein Sparkonto unmöglich viel. In welcher Zeile steckt der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Vergleiche, was in Zeile 1 vorne steht und was in Zeile 2 vorne steht.", "w": "Zeile 1 stimmt. Zeile 2 setzt die Zahlen falsch ein: Die Zinsen stehen vorne, also 32 : 800 · 100 = 4. Der Zinssatz ist 4 %. Zeile 3 folgt richtig aus Zeile 2: 2 500 % wären unmöglich viel.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 8651}, {"l": "kapital", "t": "kapital", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Kapital bringt bei 5 % im Jahr 45 € Zinsen. 1 % des Kapitals sind ① €. Das Kapital selbst ist ② €. Bei 3 % würde dasselbe Kapital im Jahr ③ € Zinsen bringen.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [9, 900, 27]}, "h": "Rechne über 1 %.", "w": "5 % sind 45 €, also ist 1 % ein Fünftel davon: 9 €. Das Kapital sind 100 %: 9 € · 100 = 900 €. 3 % davon sind 3 · 9 € = 27 €.", "form": "lueckenweg", "zaehlt": "nein", "r": 8652}, {"l": "kapital", "t": "kapital", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Ein Satz lautet: „3 % eines Kapitals sind 54 €.“ Welche Rechnung gibt das Kapital?"}, "a": ["54 € : 3 · 100", "54 € · 3 : 100", "54 € · 3", "54 € : 100 : 3"], "o": {"index": 0}, "h": "Gehe über 1 %: erst ein Prozent, dann hundert Prozent.", "w": "1 % sind 54 € : 3 = 18 €. 100 % sind 18 € · 100 = 1 800 €. Die Rechnung ist 54 € : 3 · 100.", "form": "bruecke", "zaehlt": "ja", "r": 8653}, {"l": "kapital", "t": "kapital", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Gesucht ist das Kapital. Bekannt sind die Jahreszinsen 60 € und der Zinssatz 4 %. Welches Vorgehen führt zum Ziel?"}, "a": ["Zinsen durch den Zinssatz, dann mal 100", "Zinsen mal den Zinssatz, dann durch 100", "Zinsen mal 100, dann mal den Zinssatz", "Zinssatz durch die Zinsen, dann mal 100"], "o": {"index": 0}, "h": "Der Weg geht über 1 %.", "w": "60 € : 4 = 15 € sind 1 %. 15 € · 100 = 1 500 € sind das Kapital.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 8654}, {"l": "monatszinsen", "t": "monatszinsen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Kapital von 3 000 € wird mit 2 % verzinst. Die Jahreszinsen sind ① €. Ein einzelner Monat bringt ② €. Für 4 Monate bekommt man ③ € Zinsen.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [60, 5, 20]}, "h": "Ein Jahr hat 12 Monate.", "w": "Die Jahreszinsen sind 3 000 € · 2 : 100 = 60 €. Ein Monat bringt 60 € : 12 = 5 €. 4 Monate bringen 4 · 5 € = 20 €.", "form": "lueckenweg", "zaehlt": "nein", "r": 8655}, {"l": "monatszinsen", "t": "monatszinsen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Ein Kapital von 1 800 € ist mit 4 % verzinst. Für eine bestimmte Zahl von Monaten wurden 24 € Zinsen berechnet, jeder Monat brachte gleich viel. Für wie viele Monate war das?"}, "o": {"wert": 4, "einheit": "Monate"}, "h": "Rechne zuerst, wie viel ein einzelner Monat bringt.", "w": "Jahreszinsen: 1 800 € · 4 : 100 = 72 €. Ein Monat bringt 72 € : 12 = 6 €. 24 € : 6 € = 4 Monate.", "form": "umkehren", "zaehlt": "ja", "r": 8656}, {"l": "monatszinsen", "t": "monatszinsen", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Eine Werkstatt leiht sich 6 000 € zu 9 % im Jahr und zahlt nach 8 Monaten das geliehene Geld samt den Zinsen für diese Zeit auf einmal zurück. Wie viel Euro zahlt sie insgesamt zurück?"}, "o": {"wert": 6360, "einheit": "€"}, "h": "Erst die Zinsen für 8 Monate, dann das geliehene Geld dazu.", "w": "Jahreszinsen: 6 000 € · 9 : 100 = 540 €. Für 8 Monate: 540 € · 8 : 12 = 360 €. Zurück zu zahlen sind 6 000 € + 360 € = 6 360 €.", "form": "anwenden", "zaehlt": "ja", "r": 8657}, {"l": "zeitanteil", "t": "zeitanteil", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Ein Kapital von 2 000 € ist mit 3 % verzinst, die Zinsen werden erst am Ende gezahlt. Gesucht sind die Zinsen für ein halbes Jahr. Welche Rechnung passt?"}, "a": ["2 000 € · 3 : 100 : 2", "2 000 € · 3 : 100 · 2", "2 000 € · 3 : 100 : 6", "2 000 € · 3 : 100 · 6"], "o": {"index": 0}, "h": "Ein halbes Jahr bringt die Hälfte der Jahreszinsen.", "w": "Jahreszinsen: 60 €. Ein halbes Jahr: 60 € : 2 = 30 €. Also durch 2 teilen.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 8658}, {"l": "zeitanteil", "t": "zeitanteil", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Jugendlicher legt 1 200 € aus einem Ferienjob für ein Vierteljahr zu 2 % an; das Geld bleibt angelegt. Ein Fahrrad für 300 € will er allein aus den Zinsen und eigenem Taschengeld bezahlen. Wie viel Euro muss er zu den Zinsen aus dem Taschengeld dazulegen?"}, "o": {"wert": 294, "einheit": "€"}, "h": "Ein Vierteljahr bringt ein Viertel der Jahreszinsen.", "w": "Jahreszinsen: 1 200 € · 2 : 100 = 24 €. Ein Vierteljahr: 24 € : 4 = 6 €. Es fehlen 300 € − 6 € = 294 €.", "form": "anwenden", "zaehlt": "ja", "r": 8659}, {"l": "zeitanteil", "t": "zeitanteil", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Kind rechnet die Zinsen für ein halbes Jahr bei 2 200 € und 3 %. Zeile 1: Die Jahreszinsen sind 66 €. Zeile 2: Ein halbes Jahr sind 6 von 12 Monaten. Zeile 3: Also sind die Zinsen für ein halbes Jahr 66 € · 6 = 396 €. In welcher Zeile steckt der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Vergleiche das Ergebnis mit den Jahreszinsen: Kann ein halbes Jahr mehr bringen als ein ganzes?", "w": "Zeile 1 und 2 stimmen. In Zeile 3 muss man 6/12 des Jahresbetrags nehmen: 66 € : 2 = 33 €. Das Sechsfache wären die Zinsen für sechs Jahre.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 8660}]$auf$::jsonb),
    (14, 'daten.kennwerte', 580, 9, $auf$[{"l": "mittelwert", "t": "mittelwert", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Vier Kinder haben 6, 8, 11 und 15 Punkte. Zusammen sind das ① Punkte. Bei gerechter Verteilung bekommt jedes Kind ② Punkte. Das Kind mit den meisten Punkten gibt dafür ③ Punkte ab.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [40, 10, 5]}, "h": "Erst alles zusammenzählen, dann gleichmäßig auf die Kinder verteilen.", "w": "Die Summe ist 40 Punkte. Auf 4 Kinder verteilt: 40 : 4 = 10 Punkte für jedes Kind. Das Kind mit 15 Punkten gibt 15 − 10 = 5 Punkte ab.", "form": "lueckenweg", "zaehlt": "nein", "r": 8581}, {"l": "mittelwert", "t": "mittelwert", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Fünf Messwerte sind 12; 12; 12; 14 und 20. Weg A: alle Werte addieren und durch 5 teilen. Weg B: 12 als Schätzwert nehmen, die Abweichungen der Werte von 12 addieren, diese Summe durch 5 teilen und das Ergebnis zu 12 addieren. Wie groß ist der Mittelwert?"}, "o": {"wert": 14}, "h": "Beide Wege müssen denselben Mittelwert ergeben.", "w": "Weg A: 12 + 12 + 12 + 14 + 20 = 70, also 70 : 5 = 14. Weg B: Die Abweichungen von 12 sind 0, 0, 0, 2 und 8, zusammen 10. 10 : 5 = 2, und 12 + 2 = 14. Beide Wege geben 14.", "form": "zwei_wege", "zaehlt": "ja", "r": 8582}, {"l": "mittelwert", "t": "mittelwert", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Klasse sammelt an fünf Tagen 18, 24, 15, 30 und 23 Pfandflaschen. Wie viele Flaschen sind das im Mittel pro Tag?"}, "o": {"wert": 22, "einheit": "Flaschen"}, "h": "Summe durch Anzahl der Tage.", "w": "18 + 24 + 15 + 30 + 23 = 110 Flaschen. 110 : 5 = 22 Flaschen pro Tag.", "form": "anwenden", "zaehlt": "ja", "r": 8583}, {"l": "mittel_tabelle", "t": "mittel_tabelle", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "In einer Tabelle steht: Note 1 kommt 2-mal vor, Note 2 kommt 5-mal vor, Note 3 kommt 3-mal vor. Welche Rechnung gibt die Durchschnittsnote?"}, "a": ["(1 · 2 + 2 · 5 + 3 · 3) : 10", "(1 + 2 + 3) : 3", "(2 + 5 + 3) : 3", "(1 · 2 + 2 · 5 + 3 · 3) : 3"], "o": {"index": 0}, "h": "Jede Note zählt so oft, wie sie vorkommt.", "w": "Note mal Anzahl: 2 + 10 + 9 = 21. Es sind 10 Noten, also 21 : 10 = 2,1.", "form": "bruecke", "zaehlt": "ja", "r": 8584}, {"l": "mittel_tabelle", "t": "mittel_tabelle", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "In einer Tabelle kommt der Wert 4 dreimal vor, der Wert 6 zweimal und der Wert 10 fünfmal. Weg A: jeden Wert mal seine Anzahl, addieren und durch 10 teilen. Weg B: den Anteil jedes Werts an den zehn Werten bestimmen (3/10, 2/10, 5/10), jeden Wert mit seinem Anteil malnehmen und addieren. Wie groß ist der Mittelwert?"}, "o": {"wert": 7.4}, "h": "Beide Wege müssen denselben Mittelwert ergeben.", "w": "Weg A: 4 · 3 = 12, 6 · 2 = 12 und 10 · 5 = 50, zusammen 74. 74 : 10 = 7,4. Weg B: 4 · 0,3 + 6 · 0,2 + 10 · 0,5 = 1,2 + 1,2 + 5 = 7,4.", "form": "zwei_wege", "zaehlt": "ja", "r": 8585}, {"l": "mittel_tabelle", "t": "mittel_tabelle", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "In einer Tabelle kommt der Wert 5 dreimal vor und der Wert 8 zweimal. Dazu kommt ein weiterer Wert, der einmal vorkommt. Der Mittelwert aller sechs Werte ist 7. Wie groß ist der sechste Wert?"}, "o": {"wert": 11}, "h": "Rechne zuerst die Summe aller sechs Werte.", "w": "Die Summe ist 7 · 6 = 42. Bekannt sind 5 · 3 + 8 · 2 = 31. Der sechste Wert ist 42 − 31 = 11.", "form": "umkehren", "zaehlt": "ja", "r": 8586}, {"l": "mittel_rueckwaerts", "t": "mittel_rueckwaerts", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "In vier Tests hat jemand im Mittel 10 Punkte erreicht. Die ersten drei Tests hatten 7, 12 und 8 Punkte. Wie viele Punkte hatte der vierte Test?"}, "o": {"wert": 13}, "h": "Wie hängen Mittelwert, Anzahl und Summe zusammen?", "w": "Summe aller vier Tests: 10 · 4 = 40 Punkte. Bekannt sind 7 + 12 + 8 = 27. Der vierte Test hatte 40 − 27 = 13 Punkte.", "form": "umkehren", "zaehlt": "ja", "r": 8587}, {"l": "mittel_rueckwaerts", "t": "mittel_rueckwaerts", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Läuferin ist an vier Trainingstagen im Mittel 8 km pro Tag gelaufen. Am fünften Tag läuft sie 13 km. Um wie viele Kilometer steigt der Mittelwert pro Tag durch den fünften Tag?"}, "o": {"wert": 1, "einheit": "km"}, "h": "Rechne zuerst, wie viele Kilometer es an den ersten vier Tagen zusammen waren.", "w": "Die ersten vier Tage: 8 · 4 = 32 km. Mit dem fünften Tag: 32 + 13 = 45 km. Neuer Mittelwert: 45 : 5 = 9 km. Er steigt um 9 − 8 = 1 km.", "form": "anwenden", "zaehlt": "ja", "r": 8588}, {"l": "mittel_rueckwaerts", "t": "mittel_rueckwaerts", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Ein Satz lautet: „Der Mittelwert von sechs Zahlen ist 12.“ Die Summe der sechs Zahlen heißt S. Welche Gleichung sagt dasselbe?"}, "a": ["S : 6 = 12", "S · 6 = 12", "S + 6 = 12", "S : 12 = 12"], "o": {"index": 0}, "h": "Wie wird ein Mittelwert aus der Summe berechnet?", "w": "Der Mittelwert ist die Summe geteilt durch die Anzahl: S : 6 = 12. Daraus folgt S = 12 · 6 = 72.", "form": "bruecke", "zaehlt": "ja", "r": 8589}]$auf$::jsonb),
    (30, 'raum.schraegbilder', 604, 12, $auf$[{"l": "pyramide", "t": "pyramide", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Grundfläche einer Pyramide hat 9 Ecken. Mit der Spitze hat die Pyramide ① Ecken. Von der Spitze läuft zu jeder Bodenecke eine Kante; zusammen mit den Bodenkanten hat die Pyramide ② Kanten. Die Seitenflächen sind Dreiecke; mit der Grundfläche hat die Pyramide ③ Flächen.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [10, 18, 10]}, "h": "Zähle getrennt: Boden, Spitze, Seiten.", "w": "Ecken: 9 am Boden und die Spitze, also 10. Kanten: 9 am Boden und 9 zur Spitze, also 18. Flächen: 9 Dreiecke (so viele wie Bodenkanten) und die Grundfläche, also 10.", "form": "lueckenweg", "zaehlt": "nein", "r": 8605}, {"l": "pyramide", "t": "pyramide", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Eine Pyramide hat 16 Kanten. Wie viele Ecken hat sie?"}, "o": {"wert": 9, "einheit": "Ecken"}, "h": "Wie viele Kanten gehören zum Boden, wie viele laufen zur Spitze?", "w": "2n = 16, also n = 8: die Grundfläche ist ein Achteck. Ecken: 8 + 1 = 9.", "form": "umkehren", "zaehlt": "ja", "r": 8606}, {"l": "pyramide", "t": "pyramide", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Kind beschreibt eine fünfseitige Pyramide. Zeile 1: Die Grundfläche ist ein Fünfeck, also n = 5. Zeile 2: Sie hat 5 + 1 = 6 Ecken und 2 · 5 = 10 Kanten. Zeile 3: Flächen hat sie 5, nämlich die fünf Dreiecke. In welcher Zeile steckt der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Zähle die Flächen einer fünfseitigen Pyramide selbst durch.", "w": "Zeile 1 und 2 stimmen. Zu den fünf Dreiecken kommt die Grundfläche dazu: 5 + 1 = 6 Flächen.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 8607}, {"l": "lage", "t": "lage", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "In einem Koordinatensystem liegt die Kante 1 von P(0 | 0 | 0) nach Q(4 | 0 | 0) und die Kante 2 von R(4 | 3 | 0) nach S(4 | 3 | 2). Welche Lage haben die beiden Geraden, auf denen die Kanten liegen?"}, "a": ["windschief", "parallel", "schneidend", "identisch"], "o": {"index": 0}, "h": "Vergleiche die Richtungen und prüfe, ob es einen gemeinsamen Punkt gibt.", "w": "Kante 1 läuft in x-Richtung, Kante 2 in z-Richtung: nicht dieselbe Richtung, also nicht parallel. Auf Gerade 1 ist y = 0, auf Gerade 2 ist y = 3: es gibt keinen gemeinsamen Punkt. Ohne gemeinsamen Punkt und ohne gleiche Richtung heißen die Geraden windschief.", "form": "bruecke", "zaehlt": "ja", "r": 8608}, {"l": "lage", "t": "lage", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Du sollst entscheiden, ob zwei Kanten eines Quaders parallel sind. Welches Vorgehen führt zum Ziel?"}, "a": ["prüfen, ob sie dieselbe Richtung haben", "prüfen, ob sie sich nicht schneiden", "prüfen, ob sie gleich lang sind", "prüfen, ob sie zur selben Seitenfläche gehören"], "o": {"index": 0}, "h": "Überlege, was parallele Kanten von windschiefen unterscheidet.", "w": "Parallel verlangt dieselbe Richtung. Kein Schnittpunkt genügt nicht, denn windschiefe Kanten schneiden sich auch nicht. Länge und Seitenfläche entscheiden gar nicht.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 8609}, {"l": "lage", "t": "lage", "p": "uebung", "s": 2, "g": "umkehr", "y": "auswahl", "f": {"text": "Zwei Kanten eines Quaders sind windschief. Was weiß man damit sicher über sie?"}, "a": ["Sie liegen in keiner gemeinsamen Ebene.", "Sie sind gleich lang.", "Sie schneiden sich in genau einem Punkt.", "Sie haben dieselbe Richtung."], "o": {"index": 0}, "h": "Was wäre bei parallelen oder bei schneidenden Kanten anders?", "w": "Windschiefe Geraden liegen in keiner gemeinsamen Ebene: sie treffen sich nicht und haben nicht dieselbe Richtung. Über ihre Längen sagt das nichts.", "form": "umkehren", "zaehlt": "ja", "r": 8610}, {"l": "wahre_groesse", "t": "wahre_groesse", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Im Schrägbild ist eine Kante nach hinten mit q = 0,5 gezeichnet; im Bild ist sie 3 cm lang. Ihre wahre Länge ist ① cm. Eine Kante parallel zur Zeichenebene ist im Bild 5 cm lang. Beide Kanten zusammen haben die wahre Länge ② cm.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [6, 11]}, "h": "Welche Kanten werden verkürzt, welche nicht?", "w": "3 cm : 0,5 = 6 cm wahre Länge. Die Kante parallel zur Zeichenebene wird nicht verkürzt: 5 cm. Zusammen 11 cm.", "form": "lueckenweg", "zaehlt": "nein", "r": 8611}, {"l": "wahre_groesse", "t": "wahre_groesse", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Eine Kante nach hinten ist wahr 8 cm lang und wird mit q = 0,5 gezeichnet. Weg A: 8 cm mit q malnehmen. Weg B: eine Bildlänge ausprobieren und prüfen, ob man beim Zurückrechnen (durch q) auf 8 cm kommt. Wie lang ist die Kante im Schrägbild?"}, "o": {"wert": 4, "einheit": "cm"}, "h": "Beim Zeichnen nimmst du mal q, beim Zurückrechnen teilst du durch q.", "w": "Weg A: 8 cm · 0,5 = 4 cm. Weg B: Probe mit 4 cm im Bild: 4 cm : 0,5 = 8 cm stimmt. Im Schrägbild ist die Kante 4 cm lang.", "form": "zwei_wege", "zaehlt": "ja", "r": 8612}, {"l": "wahre_groesse", "t": "wahre_groesse", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Quader ist 10 cm lang, 6 cm tief und 4 cm hoch. Seine Vorderfläche liegt in der Zeichenebene, im Schrägbild wird die Tiefe mit q = 0,5 gezeichnet. Wie lang wird die Tiefenkante im Schrägbild?"}, "o": {"wert": 3, "einheit": "cm"}, "h": "Welche Kante läuft nach hinten?", "w": "6 cm · 0,5 = 3 cm. Länge und Höhe bleiben mit 10 cm und 4 cm in wahrer Größe.", "form": "anwenden", "zaehlt": "ja", "r": 8613}, {"l": "raumwinkel", "t": "raumwinkel", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Ein gerades Prisma hat ein regelmäßiges Sechseck als Grundfläche. Zwei benachbarte Seitenflächen treffen sich an einer senkrechten Kante. Wie groß ist der Winkel zwischen ihnen?"}, "a": ["120°", "90°", "60°", "108°"], "o": {"index": 0}, "h": "Stell dir das Prisma von oben gesehen vor.", "w": "Im regelmäßigen Sechseck ist jeder Innenwinkel 120°. Beim geraden Prisma ist das auch der Winkel zwischen zwei benachbarten Seitenflächen.", "form": "bruecke", "zaehlt": "ja", "r": 8614}, {"l": "raumwinkel", "t": "raumwinkel", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Pavillon ist ein gerades Prisma mit einem regelmäßigen Fünfeck als Grundfläche. Wie groß ist der Winkel zwischen zwei benachbarten Seitenwänden?"}, "o": {"wert": 108, "einheit": "°"}, "h": "Schau von oben auf den Pavillon: Welche Figur siehst du?", "w": "Die Innenwinkelsumme ist (5 − 2) · 180° = 540°, jeder Innenwinkel also 540° : 5 = 108°. Das ist auch der Winkel zwischen den Seitenwänden.", "form": "anwenden", "zaehlt": "ja", "r": 8615}, {"l": "raumwinkel", "t": "raumwinkel", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein gerades Prisma hat ein regelmäßiges Achteck als Grundfläche. Weg A: die Innenwinkelsumme (8 − 2) · 180° durch 8 teilen. Weg B: 360° : 8 = 45° als Außenwinkel bestimmen und 180° − 45° rechnen. Wie groß ist der Winkel zwischen zwei benachbarten Seitenflächen?"}, "o": {"wert": 135, "einheit": "°"}, "h": "Beide Wege geben denselben Innenwinkel.", "w": "Weg A: (8 − 2) · 180° = 1 080°, geteilt durch 8 sind 135°. Weg B: 180° − 45° = 135°.", "form": "zwei_wege", "zaehlt": "ja", "r": 8616}]$auf$::jsonb),
    (35, 'terme.potenzgesetze', 590, 9, $auf$[{"l": "potenz_begriff", "t": "potenz_begriff", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Bei 4³ ist die Basis 4 dreimal als Faktor zu schreiben: 4 · 4 · 4. Rechne von links: 4 · 4 = ①, dann mit dem dritten Faktor ②. Das Produkt 4 · 3 der Basis mit dem Exponenten ist 12. Um ③ ist 4³ größer als dieses Produkt.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [16, 64, 52]}, "h": "Rechne Schritt für Schritt, immer mal 4.", "w": "4 · 4 = 16, dann 16 · 4 = 64. Also ist 4³ = 64 und nicht 4 · 3 = 12. Der Unterschied ist 64 − 12 = 52.", "form": "lueckenweg", "zaehlt": "nein", "r": 8591}, {"l": "potenz_begriff", "t": "potenz_begriff", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Eine Potenz mit der Basis 2 hat den Wert 64. Welchen Wert hat die Potenz mit demselben Exponenten, aber der Basis 3?"}, "o": {"wert": 729}, "h": "Finde zuerst den Exponenten: Wie oft muss 2 als Faktor stehen, damit 64 herauskommt?", "w": "2⁶ = 64, der Exponent ist also 6. Dann ist 3⁶ = 729.", "form": "umkehren", "zaehlt": "ja", "r": 8592}, {"l": "potenz_begriff", "t": "potenz_begriff", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Blatt Papier wird fünfmal in der Mitte gefaltet. Jede Faltung verdoppelt die Zahl der Lagen, vor dem Falten ist es eine Lage. Wie viele Lagen sind es danach?"}, "o": {"wert": 32, "einheit": "Lagen"}, "h": "Jede Faltung verdoppelt: 2 · 2 · 2 · …", "w": "Fünf Verdopplungen ergeben 2⁵ = 32 Lagen. 5 · 2 = 10 wäre falsch, der Exponent zählt die Faktoren.", "form": "anwenden", "zaehlt": "ja", "r": 8593}, {"l": "negativer_exponent", "t": "negativer_exponent", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Welche Zahl gehört zu 5⁻²?"}, "a": ["1/25", "−25", "−1/25", "1/10"], "o": {"index": 0}, "h": "Schau dir die Reihe 5², 5¹, 5⁰ an: Was passiert beim Weitergehen?", "w": "5⁻² = 1/5² = 1/25. Das Minus im Exponenten macht die Zahl nicht negativ, sondern bildet den Kehrbruch.", "form": "bruecke", "zaehlt": "ja", "r": 8594}, {"l": "negativer_exponent", "t": "negativer_exponent", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne 4⁻¹ + 4⁰. Weg A: beide Potenzen einzeln als Zahlen bestimmen und addieren. Weg B: 4⁻¹ ausklammern: 4⁻¹ · (1 + 4¹), denn 4⁰ = 4⁻¹ · 4¹."}, "o": {"wert": 1.25}, "h": "Beide Wege müssen denselben Wert ergeben.", "w": "Weg A: 4⁻¹ = 1/4 und 4⁰ = 1, zusammen 1/4 + 1 = 1,25. Weg B: 4⁻¹ · (1 + 4) = 1/4 · 5 = 1,25.", "form": "zwei_wege", "zaehlt": "ja", "r": 8595}, {"l": "negativer_exponent", "t": "negativer_exponent", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Eine Potenz mit der Basis 3 hat den Wert 1/27. Wie groß ist ihr (ganzzahliger) Exponent?"}, "o": {"wert": -3}, "h": "Schreibe zuerst 27 als Potenz von 3.", "w": "27 = 3³, also ist 1/27 = 3⁻³. Der Exponent ist −3.", "form": "umkehren", "zaehlt": "ja", "r": 8596}, {"l": "fehler_finden", "t": "fehler_finden", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Jemand behauptet 2⁻³ = −8. Weg A: 2⁻³ als Kehrbruch von 2³ schreiben. Weg B: bei 2¹ anfangen und immer wieder durch 2 teilen. Wie groß ist 2⁻³ wirklich?"}, "o": {"wert": 0.125}, "h": "Setze die Reihe 2³, 2², 2¹, 2⁰ fort.", "w": "Weg A: 2⁻³ = 1/2³ = 1/8. Weg B: 2; 1; 1/2; 1/4; 1/8. Beide Wege geben 1/8 = 0,125, nicht −8.", "form": "zwei_wege", "zaehlt": "ja", "r": 8597}, {"l": "fehler_finden", "t": "fehler_finden", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Bakterium teilt sich jede halbe Stunde in zwei. Jedes Bakterium teilt sich weiter, keines stirbt. Wie viele Bakterien sind es nach 4 Stunden?"}, "o": {"wert": 256, "einheit": "Bakterien"}, "h": "Rechne zuerst, wie viele Teilungen in 4 Stunden passen.", "w": "In 4 Stunden liegen 8 Teilungen. Also 2⁸ = 256 Bakterien. 2 · 8 = 16 wäre falsch.", "form": "anwenden", "zaehlt": "ja", "r": 8598}, {"l": "fehler_finden", "t": "fehler_finden", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Ein Satz lautet: „Die Zahl minus zwei wird quadriert, das Ergebnis ist 4.“ Welche Schreibweise passt dazu?"}, "a": ["(−2)²", "−2²", "2⁻²", "(−2)³"], "o": {"index": 0}, "h": "Prüfe, was genau quadriert wird.", "w": "Nur in (−2)² wird die −2 selbst quadriert: (−2) · (−2) = 4. Ohne Klammern gilt das Quadrat nur für die 2, also ist −2² = −4. 2⁻² ist der Kehrbruch 1/4, und (−2)³ = −8.", "form": "bruecke", "zaehlt": "ja", "r": 8599}]$auf$::jsonb),
    (42, 'zahlen.potenzen_zehner', 549, 21, $auf$[{"l": "zehnerpotenz", "t": "zehnerpotenz", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Zahl 100 000 000 ist eine 1 mit vielen Nullen. Man schreibt sie als 10 hoch ①. Nimmt man die Zahl dreimal hintereinander mit 10 mal, schreibt man das Ergebnis als 10 hoch ②. Das Ergebnis ist ③-mal so groß wie die alte Zahl.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [8, 11, 1000]}, "h": "Zähle die Nullen. Jeder Faktor 10 hängt eine Null an.", "w": "Hinter der 1 stehen 8 Nullen, also 10⁸. Drei Faktoren 10 mehr geben 10¹¹. Die Exponenten werden addiert (8 + 3), nicht malgenommen. 10¹¹ : 10⁸ = 10³ = 1 000.", "form": "lueckenweg", "zaehlt": "nein", "r": 8550}, {"l": "zehnerpotenz", "t": "zehnerpotenz", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Ein Lager hat 10ⁿ Fächer, nämlich 100 000. Ein größeres Lager hat 10ⁿ⁺¹ Fächer. Wie viele Fächer hat das größere Lager?"}, "o": {"wert": 1000000, "einheit": "Fächer"}, "h": "Lies zuerst n ab, dann rechne mit n + 1.", "w": "100 000 ist eine 1 mit 5 Nullen, also n = 5. Dann ist 10⁶ = 1 000 000 Fächer.", "form": "umkehren", "zaehlt": "ja", "r": 8551}, {"l": "zehnerpotenz", "t": "zehnerpotenz", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Kind erklärt 10⁶. Zeile 1: Der Exponent 6 sagt, mit wie viel man 10 malnimmt: 10⁶ = 10 · 6. Zeile 2: Also ist 10⁶ = 60. Zeile 3: Damit ist 10⁶ sechsmal so groß wie 10. In welcher Zeile steckt der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Schreibe 10³ einmal ausführlich auf.", "w": "Zeile 1 ist falsch: Der Exponent zählt die Faktoren 10, 10⁶ = 10 · 10 · 10 · 10 · 10 · 10 = 1 000 000. Die Zeilen 2 und 3 folgen richtig aus dem Fehler: 10 · 6 = 60, und 60 ist sechsmal 10.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 8552}, {"l": "gross_wissenschaftlich", "t": "gross_wissenschaftlich", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Zahl 62 000 soll als 6,2 · 10 hoch ① geschrieben werden. Die Zehnerpotenz 10 hoch ① ist ausgeschrieben die Zahl ②. Die zehnmal so große Zahl 620 000 hat bei gleicher Ziffernfolge den Exponenten ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [4, 10000, 5]}, "h": "Zähle, um wie viele Stellen das Komma wandert.", "w": "Von 62 000 zu 6,2 wandert das Komma 4 Stellen nach links, also 10⁴ = 10 000; 6,2 · 10 000 = 62 000. Die zehnmal so große Zahl braucht eine Stelle mehr: 6,2 · 10⁵ = 620 000.", "form": "lueckenweg", "zaehlt": "nein", "r": 8553}, {"l": "gross_wissenschaftlich", "t": "gross_wissenschaftlich", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Welche Schreibweise von 7 300 000 ist die wissenschaftliche?"}, "a": ["73 · 10⁵", "7,3 · 10⁶", "0,73 · 10⁷", "7,3 · 10⁵"], "o": {"index": 1}, "h": "Prüfe die Form: Wie viele Ziffern stehen vor dem Komma?", "w": "7 300 000 = 7,3 · 10⁶. Die erste und die dritte Form haben denselben Wert, sind aber nicht wissenschaftlich (zwei Ziffern bzw. eine Null vor dem Komma). 7,3 · 10⁵ wäre nur 730 000.", "form": "bruecke", "zaehlt": "ja", "r": 8554}, {"l": "gross_wissenschaftlich", "t": "gross_wissenschaftlich", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Kind schreibt 48 500 wissenschaftlich. Zeile 1: Komma hinter die erste Ziffer: 4,85. Zeile 2: Von 48 500 bis 4,85 wandert das Komma 5 Stellen nach links. Zeile 3: Also ist 48 500 = 4,85 · 10⁵. In welcher Zeile steckt der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Zähle die Stellen zwischen den beiden Kommastellungen selbst nach.", "w": "Zeile 1 stimmt. In Zeile 2 sind es nur 4 Stellen (48 500 → 4,85). Zeile 3 folgt richtig aus Zeile 2, übernimmt aber die falsche 5. Richtig ist 4,85 · 10⁴.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 8555}, {"l": "vorsilben_gross", "t": "vorsilben_gross", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Mega bedeutet 10⁶. Giga ist tausendmal so viel wie Mega. Ein Kraftwerk leistet 3 GW. Das sind 3 · 10 hoch ① Watt. In Megawatt sind es ② MW. In Kilowatt sind es ③ kW.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [9, 3000, 3000000]}, "h": "Giga steht eine Stufe über Mega. Kilo ist tausendmal kleiner als Mega.", "w": "Giga = 1 000 · 10⁶ = 10⁹, also 3 GW = 3 · 10⁹ W. In MW: 3 · 10⁹ : 10⁶ = 3 000 MW. 1 MW sind 1 000 kW, also 3 000 · 1 000 = 3 000 000 kW.", "form": "lueckenweg", "zaehlt": "nein", "r": 8556}, {"l": "vorsilben_gross", "t": "vorsilben_gross", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Rechenzentrum braucht 12 MW Leistung. Ein Windrad liefert 3 000 kW. Wie viele Windräder braucht man dafür?"}, "o": {"wert": 4, "einheit": "Windräder"}, "h": "Rechne beide Angaben zuerst in Watt um.", "w": "12 MW = 12 000 000 W und 3 000 kW = 3 000 000 W. 12 000 000 : 3 000 000 = 4 Windräder.", "form": "anwenden", "zaehlt": "ja", "r": 8557}, {"l": "vorsilben_gross", "t": "vorsilben_gross", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Kind rechnet 7 TB in Byte um. Zeile 1: Tera bedeutet 10⁹. Zeile 2: Also sind 7 TB = 7 · 10⁹ Byte. Zeile 3: Das sind 7 000 Millionen Byte. In welcher Zeile steckt der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Tera steht über Giga (10⁹).", "w": "Zeile 1 ist falsch: Tera bedeutet 10¹², nicht 10⁹. Die Zeilen 2 und 3 folgen richtig aus dem Fehler (7 · 10⁹ sind 7 000 Millionen). Richtig wären 7 · 10¹² Byte, also 7 000 000 Millionen.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 8558}, {"l": "negativer_exponent", "t": "negativer_exponent", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Zahl 0,000001 schreibt man als 10 hoch minus ①. Zwischen dem Komma und der 1 stehen ② Nullen. Eine 10 000-mal so große Zahl schreibt man als 10 hoch minus ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [6, 5, 2]}, "h": "Die Stelle der 1 nach dem Komma ist der Exponent ohne Minus.", "w": "Die 1 steht an der 6. Stelle nach dem Komma: 10⁻⁶. Davor stehen 5 Nullen. Mal 10 000 = mal 10⁴ macht aus 10⁻⁶ die Zahl 10⁻².", "form": "lueckenweg", "zaehlt": "nein", "r": 8559}, {"l": "negativer_exponent", "t": "negativer_exponent", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Wie viele Nullen stehen bei 10⁻⁴ zwischen dem Komma und der 1? Weg A: vom Exponenten 1 abziehen. Weg B: die Zahl hinschreiben und die Nullen zählen."}, "o": {"wert": 3}, "h": "Schreibe 10⁻¹, 10⁻² und 10⁻³ als Dezimalzahlen hin.", "w": "Weg A: 4 − 1 = 3. Weg B: 10⁻⁴ = 0,0001, zwischen Komma und 1 stehen 3 Nullen.", "form": "zwei_wege", "zaehlt": "ja", "r": 8560}, {"l": "negativer_exponent", "t": "negativer_exponent", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Kind sagt zu 10⁻² : Zeile 1: Der Exponent ist negativ. Zeile 2: Also ist die Zahl negativ. Zeile 3: Deshalb ist 10⁻² = −0,01. In welcher Zeile steckt der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Wie ist 10⁻¹ aus 10⁰ = 1 entstanden?", "w": "Zeile 1 stimmt. Zeile 2 ist falsch: Ein negativer Exponent macht die Zahl klein, nicht negativ. 10⁻² = 0,01. Zeile 3 folgt richtig aus Zeile 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 8561}, {"l": "klein_wissenschaftlich", "t": "klein_wissenschaftlich", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Zahl 0,00036 schreibt man wissenschaftlich als 3,6 · 10 hoch minus ①. Die zehnmal so große Zahl hat bei gleicher Ziffernfolge den Exponenten minus ②. Die tausendmal kleinere Zahl hat den Exponenten minus ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [4, 3, 7]}, "h": "Zähle die Stellen, die das Komma nach rechts wandert.", "w": "0,00036 = 3,6 · 10⁻⁴ (das Komma wandert 4 Stellen). Zehnmal so groß ist 0,0036 = 3,6 · 10⁻³. Tausendmal kleiner ist 0,00000036 = 3,6 · 10⁻⁷.", "form": "lueckenweg", "zaehlt": "nein", "r": 8562}, {"l": "klein_wissenschaftlich", "t": "klein_wissenschaftlich", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Eine Zahl ist 2,5 · 10⁻³. Wie viele Stellen hat diese Zahl nach dem Komma?"}, "o": {"wert": 4}, "h": "Schreibe die Zahl als Dezimalzahl hin.", "w": "2,5 · 10⁻³ = 0,0025. Die 2 steht an der 3. Stelle, die 5 an der 4. Stelle: 4 Stellen nach dem Komma.", "form": "umkehren", "zaehlt": "ja", "r": 8563}, {"l": "klein_wissenschaftlich", "t": "klein_wissenschaftlich", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Welche Dezimalzahl gehört zu 8,4 · 10⁻⁵?"}, "a": ["0,000084", "0,00084", "0,0000084", "840 000"], "o": {"index": 0}, "h": "Die erste Ziffer steht an der fünften Stelle nach dem Komma.", "w": "Bei 10⁻⁵ steht die 8 an der 5. Stelle nach dem Komma: 0,000084.", "form": "bruecke", "zaehlt": "ja", "r": 8564}, {"l": "vorsilben_klein", "t": "vorsilben_klein", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Milli bedeutet 10⁻³, Mikro bedeutet 10⁻⁶. Ein Millimeter besteht aus ① Mikrometern. Ein Bakterium ist 2 µm lang. Hintereinander passen ② Bakterien in einen Millimeter und ③ Bakterien in einen Meter.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [1000, 500, 500000]}, "h": "Vergleiche die beiden Exponenten.", "w": "10⁻³ : 10⁻⁶ = 10³ = 1 000, ein Millimeter hat also 1 000 µm. 1 000 : 2 = 500 Bakterien in einem Millimeter. Ein Meter hat 1 000 mm: 500 · 1 000 = 500 000 Bakterien.", "form": "lueckenweg", "zaehlt": "nein", "r": 8565}, {"l": "vorsilben_klein", "t": "vorsilben_klein", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Schutzfolie ist 250 nm dick. Wie viele solche Folien ergeben übereinander genau 1 mm?"}, "o": {"wert": 4000, "einheit": "Folien"}, "h": "Rechne beide Längen in Nanometer um.", "w": "1 mm = 10⁻³ m = 10⁶ nm. 10⁶ : 250 = 4 000 Folien.", "form": "anwenden", "zaehlt": "ja", "r": 8566}, {"l": "vorsilben_klein", "t": "vorsilben_klein", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Eine Messung dauert 7 ms. Welche Rechnung gibt die Zeit in Sekunden?"}, "a": ["7 · 10⁻³ s", "7 · 10³ s", "7 · 10⁻² s", "7 · 10⁻⁶ s"], "o": {"index": 0}, "h": "Milli bedeutet 10⁻³.", "w": "7 ms = 7 · 10⁻³ s = 0,007 s.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 8567}, {"l": "vergleichen_pruefen", "t": "vergleichen_pruefen", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Du sollst 3 · 10⁷ und 8 · 10⁶ vergleichen (beide in wissenschaftlicher Schreibweise). Welches Vorgehen führt sicher zum Ziel?"}, "a": ["zuerst die Exponenten vergleichen, bei Gleichheit die Zahl davor", "zuerst die Zahlen vor der Zehnerpotenz vergleichen", "die Exponenten addieren und die Summen vergleichen", "die Ziffern beider Zahlen zählen"], "o": {"index": 0}, "h": "Welcher Teil entscheidet über die Größenordnung?", "w": "7 ist größer als 6, also ist 3 · 10⁷ = 30 000 000 größer als 8 · 10⁶ = 8 000 000. Die Zahl vor der Potenz entscheidet nur bei gleichem Exponenten.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 8568}, {"l": "vergleichen_pruefen", "t": "vergleichen_pruefen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Wie oft passt 4 · 10³ in 2 · 10⁵? Weg A: beide Zahlen ausschreiben und teilen. Weg B: 2 : 4 rechnen und 10⁵ : 10³ dazunehmen."}, "o": {"wert": 50}, "h": "Teile die Zahlen davor und die Zehnerpotenzen getrennt.", "w": "Weg A: 200 000 : 4 000 = 50. Weg B: 2 : 4 = 0,5 und 10⁵ : 10³ = 100, also 0,5 · 100 = 50.", "form": "zwei_wege", "zaehlt": "ja", "r": 8569}, {"l": "vergleichen_pruefen", "t": "vergleichen_pruefen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Zwei Landkreise werden zusammengelegt. Der eine hat 3 · 10⁵ Einwohner, der andere 7 · 10⁴. Wie viele Einwohner hat der neue Landkreis?"}, "o": {"wert": 370000, "einheit": "Einwohner"}, "h": "Schreibe beide Zahlen zuerst normal hin.", "w": "3 · 10⁵ = 300 000 und 7 · 10⁴ = 70 000. Zusammen sind das 370 000 Einwohner.", "form": "anwenden", "zaehlt": "ja", "r": 8570}]$auf$::jsonb),
    (56, 'daten.boxplot', 581, 18, $auf$[{"l": "median", "t": "median", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die sechs Werte 10; 4; 16; 6; 12; 8 sollen ihren Median bekommen. Man ordnet sie zuerst der Größe nach. Dann stehen in der Mitte zwei Werte; ihre Summe ist ①. Der Median ist die Hälfte davon: ②. Er liegt um ③ über dem kleinsten Wert.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [18, 9, 5]}, "h": "Ordne zuerst, dann suche die Mitte.", "w": "Geordnet: 4; 6; 8; 10; 12; 16. In der Mitte stehen 8 und 10, ihre Summe ist 18. Der Median ist 18 : 2 = 9. Der kleinste Wert ist 4, also liegt der Median um 9 − 4 = 5 darüber.", "form": "lueckenweg", "zaehlt": "nein", "r": 8582}, {"l": "median", "t": "median", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Fünf Werte stehen der Größe nach geordnet da: 2; 5; x; 11; 14. Der Median ist um 4 größer als der zweite Wert. Wie groß ist x?"}, "o": {"wert": 9}, "h": "Welche Stelle in einer Reihe aus fünf geordneten Werten ist die Mitte?", "w": "Der Median ist der dritte Wert, also x. Er ist 5 + 4 = 9. Die Reihenfolge stimmt dann auch: 9 liegt zwischen 5 und 11.", "form": "umkehren", "zaehlt": "ja", "r": 8583}, {"l": "median", "t": "median", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Kind bestimmt den Median von 8; 2; 11; 5; 14. Zeile 1: Der Median ist der mittlere Wert der der Größe nach geordneten Liste. Zeile 2: In der Mitte der Liste 8; 2; 11; 5; 14 steht die 11, also ist der Median 11. Zeile 3: Es sind fünf Werte, deshalb gibt es genau einen mittleren Wert. In welcher Zeile steckt der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Bestimme den Median selbst und vergleiche.", "w": "Zeile 1 stimmt. Zeile 2 ordnet die Liste nicht: Geordnet ist 2; 5; 8; 11; 14, der mittlere Wert ist 8. Zeile 3 ist für sich richtig: bei fünf Werten gibt es einen mittleren Wert.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 8584}, {"l": "kennwerte", "t": "kennwerte", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Fünf Kinder haben 3, 7, 7, 9 und 14 Bücher. Zusammen sind das ① Bücher. Der Mittelwert ist ② Bücher. Das Kind mit den meisten Büchern hat ③ Bücher mehr als der Mittelwert.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [40, 8, 6]}, "h": "Summe durch Anzahl.", "w": "3 + 7 + 7 + 9 + 14 = 40 und 40 : 5 = 8 Bücher. Das größte Kind hat 14 − 8 = 6 Bücher mehr. Der häufigste Wert wäre 7, die Spannweite 11.", "form": "lueckenweg", "zaehlt": "nein", "r": 8585}, {"l": "kennwerte", "t": "kennwerte", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Sechs Zeiten sind 21; 25; 19; 30; 25 und 22 Sekunden. Weg A: größten und kleinsten Wert suchen und voneinander abziehen. Weg B: alle Werte ordnen und die Abstände zwischen je zwei benachbarten Werten addieren. Wie groß ist die Spannweite?"}, "o": {"wert": 11, "einheit": "s"}, "h": "Beide Wege müssen dieselbe Spannweite ergeben.", "w": "Weg A: Der größte Wert ist 30 s, der kleinste 19 s: 30 − 19 = 11 s. Weg B: geordnet 19; 21; 22; 25; 25; 30, die Abstände sind 2, 1, 3, 0 und 5, zusammen 11 s.", "form": "zwei_wege", "zaehlt": "ja", "r": 8586}, {"l": "kennwerte", "t": "kennwerte", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Verein notiert an sechs Tagen die Besucherzahlen 24, 30, 24, 31, 24 und 29. Um wie viel liegt der Mittelwert über dem häufigsten Wert?"}, "o": {"wert": 3}, "h": "Rechne erst den Mittelwert, dann suche den häufigsten Wert.", "w": "Die Summe ist 162, der Mittelwert 162 : 6 = 27. Der häufigste Wert ist 24 (dreimal). 27 − 24 = 3.", "form": "anwenden", "zaehlt": "ja", "r": 8587}, {"l": "mittel_median", "t": "mittel_median", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Ein Satz lautet: „Bei diesen Daten ist der Mittelwert größer als der Median.“ Welche Zahlenreihe passt dazu?"}, "a": ["1; 2; 3; 4; 30", "2; 3; 4; 5; 6", "1; 2; 3; 4; 5", "1; 30; 31; 32; 33"], "o": {"index": 0}, "h": "Rechne bei jeder Reihe Mittelwert und Median aus.", "w": "Reihe 1: Mittelwert 40 : 5 = 8, Median 3 – der Mittelwert ist größer. Reihe 2 und 3: Mittelwert und Median sind gleich (4 bzw. 3). Reihe 4: Mittelwert 127 : 5 = 25,4, Median 31 – der Mittelwert ist kleiner.", "form": "bruecke", "zaehlt": "ja", "r": 8588}, {"l": "mittel_median", "t": "mittel_median", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "In einer Gruppe verdienen fünf Personen 1 800 €, 1 900 €, 2 000 €, 2 100 € und 12 000 €. Du sollst den Verdienst angeben, der zu den meisten Personen der Gruppe passt. Welches Vorgehen passt?"}, "a": ["den Median nehmen, weil ein Ausreißer dabei ist", "den Mittelwert nehmen, weil er alle Werte benutzt", "die Spannweite nehmen", "den größten Wert nehmen"], "o": {"index": 0}, "h": "Vergleiche die fünf Werte miteinander: Was fällt auf?", "w": "Der Median ist 2 000 €, der Mittelwert 3 960 €. Vier der fünf Personen verdienen rund 2 000 €; der Median beschreibt die Gruppe deshalb besser.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 8589}, {"l": "mittel_median", "t": "mittel_median", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Kind vergleicht Mittelwert und Median von 8; 11; 11; 14; 101. Zeile 1: Der Median ist der Mittelwert aus kleinstem und größtem Wert: (8 + 101) : 2 = 54,5. Zeile 2: Der Mittelwert aller fünf Werte ist 145 : 5 = 29. Zeile 3: Also liegt der Median weit über dem Mittelwert. In welcher Zeile steckt der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Ordne die Werte und suche den mittleren.", "w": "Zeile 1 ist falsch: Der Median ist der mittlere Wert der geordneten Liste, also 11. Zeile 2 ist richtig (8 + 11 + 11 + 14 + 101 = 145). Zeile 3 folgt richtig aus Zeile 1 und 2 – mit dem richtigen Median 11 läge der Median dagegen weit unter dem Mittelwert.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 8590}, {"l": "quartile", "t": "quartile", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Acht Werte stehen geordnet da: 2; 5; 7; 9; 11; 14; 18; 21. Die untere Hälfte besteht aus den vier kleinsten Werten. Die beiden mittleren Werte dieser Hälfte haben die Summe ①. Ihr Median ist Q₁ = ②. Q₃ ist der Median der oberen Hälfte: ③. Der Abstand von Q₁ bis Q₃ ist ④.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [12, 6, 16, 10]}, "h": "Q₁ und Q₃ sind die Mediane der beiden Hälften.", "w": "Untere Hälfte 2; 5; 7; 9: mittlere Werte 5 und 7, Summe 12, Q₁ = 6. Obere Hälfte 11; 14; 18; 21: mittlere Werte 14 und 18, Q₃ = 16. Abstand: 16 − 6 = 10.", "form": "lueckenweg", "zaehlt": "nein", "r": 8591}, {"l": "quartile", "t": "quartile", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Neun Werte stehen geordnet da: 1; 2; 4; 5; 7; 8; 10; 11; 15. Weg A: den Median streichen und von der unteren Hälfte den Median nehmen. Weg B: die Stelle (9 + 1) : 4 = 2,5 ausrechnen, an der ein Viertel der Reihe erreicht ist, und den Wert in der Mitte zwischen dem 2. und dem 3. Wert nehmen. Wie groß ist Q₁?"}, "o": {"wert": 3}, "h": "Beide Wege müssen denselben Wert ergeben.", "w": "Weg A: Der Median ist 7. Die untere Hälfte ist 1; 2; 4; 5, ihr Median ist (2 + 4) : 2 = 3. Weg B: Zwischen dem 2. Wert (2) und dem 3. Wert (4) liegt die Mitte 3. Beide Wege geben hier 3.", "form": "zwei_wege", "zaehlt": "ja", "r": 8592}, {"l": "quartile", "t": "quartile", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Bei einem Datensatz ist Q₁ = 14, und die Box eines Boxplots ist 12 Einheiten breit. Wie groß ist Q₃?"}, "o": {"wert": 26}, "h": "Was misst die Breite der Box?", "w": "Die Breite der Box ist Q₃ − Q₁. Also ist Q₃ = 14 + 12 = 26.", "form": "umkehren", "zaehlt": "ja", "r": 8593}, {"l": "boxplot", "t": "boxplot", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Boxplot zeigt: kleinster Wert 8, Q₁ = 16, Median 22, Q₃ = 30, größter Wert 40. Die Box ist ① Einheiten breit. Der ganze Boxplot (von ganz links bis ganz rechts) ist ② Einheiten lang. Die beiden Antennen zusammen sind ③ Einheiten lang.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [14, 32, 18]}, "h": "Ziehe jeweils die beiden Randwerte voneinander ab.", "w": "Die Box ist 30 − 16 = 14 breit, der ganze Boxplot 40 − 8 = 32 lang. Für die Antennen bleibt 32 − 14 = 18: links 16 − 8 = 8, rechts 40 − 30 = 10.", "form": "lueckenweg", "zaehlt": "nein", "r": 8594}, {"l": "boxplot", "t": "boxplot", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "In einem Boxplot liegt der Median bei 23 und Q₃ bei 30. Welcher Satz passt dazu?"}, "a": ["Etwa drei Viertel der Werte sind höchstens 30.", "Etwa drei Viertel der Werte sind höchstens 23.", "Genau 30 Werte liegen in der Box.", "Der größte Wert ist 30."], "o": {"index": 0}, "h": "Was bedeutet die Lage von Q₃?", "w": "Links von Q₃ liegen drei Viertel der Werte, also sind etwa 75 % höchstens 30. Links vom Median liegt die Hälfte.", "form": "bruecke", "zaehlt": "ja", "r": 8595}, {"l": "boxplot", "t": "boxplot", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Boxplot zeigt die Wartezeiten von 40 Personen. Q₃ liegt bei 25 Minuten. Wie viele Personen haben etwa länger als 25 Minuten gewartet?"}, "o": {"wert": 10, "einheit": "Personen"}, "h": "Welcher Anteil der Werte liegt rechts von Q₃?", "w": "Rechts von Q₃ liegt ein Viertel der Daten: 40 : 4 = 10 Personen.", "form": "anwenden", "zaehlt": "ja", "r": 8596}, {"l": "vergleichen", "t": "vergleichen", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Zwei Klassen haben Laufzeiten gemessen, beide Boxplots liegen vor. Du sollst sagen, welche Klasse in der Mitte schneller ist. Welches Vorgehen passt?"}, "a": ["die Mediane der beiden Boxplots vergleichen", "die Spannweiten vergleichen", "die längsten Antennen vergleichen", "die Anzahl der Kinder vergleichen"], "o": {"index": 0}, "h": "Lies noch einmal, was genau verglichen werden soll.", "w": "Die Mitte beschreibt der Median. Spannweite und Antennen zeigen die Streuung; die Anzahl der Kinder sagt über die Zeiten nichts.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 8597}, {"l": "vergleichen", "t": "vergleichen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Klasse A hat den Median 24 s, ihre Box reicht von 22 s bis 26 s. Klasse B hat den Median 22 s, ihre Box reicht von 18 s bis 27 s. Um wie viele Sekunden ist die Box von B breiter als die von A?"}, "o": {"wert": 5, "einheit": "s"}, "h": "Rechne beide Boxbreiten einzeln aus.", "w": "Box A: 26 − 22 = 4 s. Box B: 27 − 18 = 9 s. 9 − 4 = 5 s: in B streuen die Zeiten mehr.", "form": "anwenden", "zaehlt": "ja", "r": 8598}, {"l": "vergleichen", "t": "vergleichen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Kind vergleicht zwei Boxplots. Zeile 1: Klasse A hat die Spannweite 20, Klasse B die Spannweite 12. Zeile 2: Gemessen an der Spannweite streuen die Werte bei A also stärker. Zeile 3: Deshalb hat Klasse A mehr Kinder als Klasse B. In welcher Zeile steckt der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Sagt eine Spannweite etwas über die Anzahl der Kinder?", "w": "Zeile 1 und 2 stimmen. Die Spannweite zeigt nur, wie weit die Werte auseinanderliegen. Über die Anzahl der Kinder sagt ein Boxplot nichts.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 8599}]$auf$::jsonb),
    (58, 'geometrie.kreis', 541, 18, $auf$[{"l": "thales", "t": "thales", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Im Dreieck ABC ist [AB] ein Durchmesser des Kreises, C liegt auf dem Kreis. Bei A sind 28°. Der Winkel bei C ist ①°. Der Winkel bei B ist ②°. Der Nebenwinkel des Winkels bei B ist ③°.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [90, 62, 118]}, "h": "Wo liegt C in Bezug auf den Durchmesser?", "w": "Nach dem Satz des Thales sind es bei C 90°. Dann bleiben 180° − 90° − 28° = 62° für den Winkel bei B. Der Nebenwinkel ergänzt auf 180°: 180° − 62° = 118°.", "form": "lueckenweg", "zaehlt": "nein", "r": 8542}, {"l": "thales", "t": "thales", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Im Dreieck ABC liegt C auf dem Kreis über dem Durchmesser [AB]. Der Winkel bei B ist doppelt so groß wie der Winkel bei A. Wie groß ist der Winkel bei A?"}, "o": {"wert": 30, "einheit": "°"}, "h": "Die Winkel bei A und B ergeben zusammen 90°.", "w": "Bei C sind 90°, also bleiben für A und B zusammen 90°. Mit β = 2α folgt 3α = 90°, also α = 30°.", "form": "umkehren", "zaehlt": "ja", "r": 8543}, {"l": "thales", "t": "thales", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Kind untersucht ein Dreieck ABC, dessen Ecken A, B und C auf einem Kreis liegen. Die Strecke [AB] geht nicht durch den Mittelpunkt. Zeile 1: Weil A und B auf dem Kreis liegen, ist [AB] ein Durchmesser. Zeile 2: Also gilt für den Punkt C der Satz des Thales. Zeile 3: Der Winkel bei C ist deshalb 90°. In welcher Zeile steckt der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Welche Bedingung muss die Strecke [AB] erfüllen?", "w": "Zeile 1 ist falsch: Ein Durchmesser geht durch den Mittelpunkt, [AB] tut das hier nicht. Die Zeilen 2 und 3 folgen richtig aus der falschen Zeile 1. Ohne Durchmesser ist der Winkel bei C meist kein rechter.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 8544}, {"l": "umkehrung", "t": "umkehrung", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Bei C ist ein rechter Winkel, und es ist A(1 | 2) und B(9 | 2). Nach der Umkehrung des Satzes von Thales liegt C auf dem Kreis über [AB]. Der Mittelpunkt M hat die x-Koordinate ①. Der Radius ist ② lang. Der höchste Punkt des Kreises hat die y-Koordinate ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [5, 4, 6]}, "h": "Der Mittelpunkt liegt genau zwischen A und B.", "w": "Die Mitte von 1 und 9 ist (1 + 9) : 2 = 5, also M(5 | 2). Der Radius ist der Abstand von M zu A: 5 − 1 = 4. Der höchste Punkt liegt 4 über M: y = 2 + 4 = 6.", "form": "lueckenweg", "zaehlt": "nein", "r": 8545}, {"l": "umkehrung", "t": "umkehrung", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "In einem Koordinatensystem sind A(−3 | 0) und B(3 | 0) gegeben. Bei welchem Punkt C hat das Dreieck ABC bei C einen rechten Winkel?"}, "a": ["C(0 | 3)", "C(3 | 3)", "C(0 | 4)", "C(2 | 2)"], "o": {"index": 0}, "h": "Wie weit ist C vom Mittelpunkt der Strecke [AB] entfernt, und wie weit müsste er es sein?", "w": "Der Kreis über [AB] hat den Mittelpunkt (0 | 0) und den Radius 3. Nur C(0 | 3) liegt darauf. Bei C(3 | 3) liegt der rechte Winkel bei B, C(0 | 4) liegt außerhalb des Kreises (Winkel kleiner als 90°), C(2 | 2) innerhalb (Winkel größer als 90°).", "form": "bruecke", "zaehlt": "ja", "r": 8546}, {"l": "umkehrung", "t": "umkehrung", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Tischler prüft ein dreieckiges Brettstück ABC. Die Kante [AB] ist 50 cm lang. Er will wissen, ob bei C genau 90° sind. Dazu sticht er in die Mitte von [AB] ein und misst von dort bis zur Ecke C. Welchen Abstand muss er finden, wenn der Winkel bei C genau 90° ist?"}, "o": {"wert": 25, "einheit": "cm"}, "h": "Welcher Kreis gehört zu rechten Winkeln über [AB]?", "w": "Der Kreis über der 50 cm langen Kante hat den Radius 50 cm : 2 = 25 cm. Liegt die Ecke C auf diesem Kreis, ist der Winkel 90°, der Abstand muss also 25 cm sein.", "form": "anwenden", "zaehlt": "ja", "r": 8547}, {"l": "beweis", "t": "beweis", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Du sollst zeigen, dass bei jedem Punkt C auf dem Thaleskreis ein rechter Winkel entsteht. Welches Vorgehen ist ein Beweis?"}, "a": ["mit den gleich langen Radien MA, MB und MC argumentieren", "zwanzig Beispiele zeichnen und nachmessen", "ein besonders großes Dreieck zeichnen und messen", "den Satz in einem Buch nachlesen"], "o": {"index": 0}, "h": "Welches Vorgehen deckt auch einen Punkt C ab, den du nie gezeichnet hast?", "w": "MA, MB und MC sind Radien, also gleich lang. Daraus ergeben sich zwei gleichschenklige Dreiecke, und die Winkelsumme führt auf 90° bei C – für jeden Punkt C. Messen liefert nur eine Vermutung.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 8548}, {"l": "beweis", "t": "beweis", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Im Dreieck ABC ist [AB] ein Durchmesser, der Winkel bei A ist 40°. Weg A: 180° − 90° − 40° rechnen. Weg B: Im gleichschenkligen Dreieck AMC ist der Winkel bei M 100°, also ist der Winkel BMC 80°; im gleichschenkligen Dreieck BMC sind die beiden Basiswinkel gleich groß. Wie groß ist der Winkel bei B?"}, "o": {"wert": 50, "einheit": "°"}, "h": "Beide Wege müssen denselben Winkel ergeben.", "w": "Weg A: 180° − 90° − 40° = 50°. Weg B: (180° − 80°) : 2 = 50°. Beide Wege geben 50°.", "form": "zwei_wege", "zaehlt": "ja", "r": 8549}, {"l": "beweis", "t": "beweis", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Kind schreibt: Zeile 1: Ich habe in zwanzig Dreiecken über einem Durchmesser den Winkel bei C gemessen. Zeile 2: Jedes Mal kamen 90° heraus. Zeile 3: Damit ist der Satz des Thales bewiesen. In welcher Zeile steckt der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Was zeigen zwanzig Beispiele, und was zeigen sie nicht?", "w": "Zeile 1 und 2 beschreiben eine saubere Messreihe. Sie gilt aber nur für diese zwanzig Dreiecke. Ein Beweis muss für alle Punkte C gelten; dafür braucht man die gleich langen Radien.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 8550}, {"l": "lage", "t": "lage", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Kreis hat den Radius 5 cm. Eine Gerade hat vom Mittelpunkt den Abstand 8 cm. Man schiebt die Gerade um 6 cm zum Mittelpunkt hin. Ihr neuer Abstand ist ① cm. Der Unterschied zum Radius beträgt ② cm. Die Anzahl der gemeinsamen Punkte von Gerade und Kreis ist ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [2, 3, 2]}, "h": "Vergleiche den neuen Abstand mit dem Radius.", "w": "Neuer Abstand: 8 cm − 6 cm = 2 cm. Das sind 5 cm − 2 cm = 3 cm weniger als der Radius. Ist der Abstand kleiner als der Radius, schneidet die Gerade den Kreis in 2 Punkten (Sekante).", "form": "lueckenweg", "zaehlt": "nein", "r": 8551}, {"l": "lage", "t": "lage", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Gegeben sind ein Kreis mit dem Radius 6 cm und eine Gerade g. Du sollst herausfinden, ob g Passante, Tangente oder Sekante ist. Welches Vorgehen führt zum Ziel?"}, "a": ["den Abstand des Mittelpunkts von g bestimmen und mit 6 cm vergleichen", "die Länge der Geraden g messen", "den Umfang des Kreises berechnen", "den Abstand des Mittelpunkts zu einem beliebigen Punkt von g messen"], "o": {"index": 0}, "h": "Was ändert sich, wenn man die Gerade immer weiter vom Mittelpunkt wegschiebt?", "w": "Man vergleicht den Abstand des Mittelpunkts von der Geraden mit dem Radius: größer heißt Passante, gleich Tangente, kleiner Sekante.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 8552}, {"l": "lage", "t": "lage", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein kreisrunder Teich hat den Durchmesser 24 m. Ein gerader Zaun soll so verlaufen, dass er den Teichrand an genau einer Stelle berührt. Welchen Abstand muss der Zaun von der Mitte des Teichs haben?"}, "o": {"wert": 12, "einheit": "m"}, "h": "Wie viele Punkte soll der Zaun mit dem Teichrand gemeinsam haben?", "w": "Der Radius ist 24 m : 2 = 12 m. Eine Tangente hat genau den Abstand des Radius, also 12 m.", "form": "anwenden", "zaehlt": "ja", "r": 8553}, {"l": "tangente", "t": "tangente", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Von einem Punkt P außerhalb eines Kreises gehen zwei Tangenten aus. In jedem Berührpunkt bildet die Tangente mit dem Berührradius einen Winkel von ①°. Im Viereck aus P, den beiden Berührpunkten und dem Mittelpunkt M ist die Winkelsumme 360°. Ist der Winkel bei P gleich 40°, so ist der Winkel bei M gleich ②°. Die Gerade MP halbiert ihn; jede Hälfte hat ③°.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [90, 140, 70]}, "h": "Wie stehen Tangente und Berührradius zueinander?", "w": "An beiden Berührpunkten sind es 90°. 360° − 90° − 90° − 40° = 140° bei M. Die Hälfte davon ist 70°.", "form": "lueckenweg", "zaehlt": "nein", "r": 8554}, {"l": "tangente", "t": "tangente", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Von einem Punkt P gehen zwei Tangenten an einen Kreis. Zwischen den beiden Berührradien liegt beim Mittelpunkt ein Winkel von 110°. Wie groß ist der Winkel bei P?"}, "o": {"wert": 70, "einheit": "°"}, "h": "Zeichne das Viereck aus P, den beiden Berührpunkten und dem Mittelpunkt.", "w": "Im Viereck sind die Winkel an den Berührpunkten je 90°. 360° − 90° − 90° − 110° = 70°. Bei P ist der Winkel 70°.", "form": "umkehren", "zaehlt": "ja", "r": 8555}, {"l": "tangente", "t": "tangente", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Von einem Punkt P gehen zwei Tangenten an einen Kreis mit dem Mittelpunkt M; die Berührpunkte heißen B und B'. Der Weg von B über P nach B' ist 24 cm lang. Weg A: die Regel anwenden, dass die beiden Tangentenabschnitte von P gleich lang sind. Weg B: die Dreiecke PMB und PMB' vergleichen (gemeinsame Seite [PM], gleiche Radien, je ein rechter Winkel). Wie lang ist die Strecke [PB]?"}, "o": {"wert": 12, "einheit": "cm"}, "h": "Beide Wege sagen dasselbe über [PB] und [PB'].", "w": "Weg A: beide Abschnitte sind gleich lang, also 24 cm : 2 = 12 cm. Weg B: Die Dreiecke PMB und PMB' stimmen in [PM], im Radius und im rechten Winkel überein (kongruent), deshalb ist [PB] = [PB']. Beide Wege geben 12 cm.", "form": "zwei_wege", "zaehlt": "ja", "r": 8556}, {"l": "umkreis_inkreis", "t": "umkreis_inkreis", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Dreieck hat die Ecken A(0 | 0), B(8 | 0) und C(0 | 6). Der Umkreismittelpunkt M ist der Schnittpunkt der Mittelsenkrechten. Die Mittelsenkrechte von [AB] ist die Senkrechte durch x = ①, die Mittelsenkrechte von [AC] die Waagerechte durch y = ②. Von A aus muss man zu M also ① nach rechts und ② nach oben gehen, zusammen ③ Einheiten auf den Achsen.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [4, 3, 7]}, "h": "Jede Mittelsenkrechte geht durch die Mitte ihrer Strecke.", "w": "Die Mitte von [AB] ist (4 | 0), die Mitte von [AC] ist (0 | 3). Der Umkreismittelpunkt ist M(4 | 3). Der Weg von A aus: 4 + 3 = 7 Einheiten.", "form": "lueckenweg", "zaehlt": "nein", "r": 8557}, {"l": "umkreis_inkreis", "t": "umkreis_inkreis", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Ein Kind zeichnet in ein Dreieck die drei Winkelhalbierenden und nimmt ihren Schnittpunkt S. Dann zeichnet es um S einen Kreis, der eine der drei Seiten berührt. Welche Eigenschaft hat dieser Kreis?"}, "a": ["Er berührt alle drei Seiten des Dreiecks (Inkreis).", "Er geht durch alle drei Ecken des Dreiecks (Umkreis).", "Er berührt nur die gewählte Seite und schneidet die beiden anderen.", "Sein Mittelpunkt liegt immer auf der längsten Seite."], "o": {"index": 0}, "h": "Was haben alle Punkte einer Winkelhalbierenden gemeinsam?", "w": "S hat zu allen drei Seiten denselben Abstand. Ein Kreis um S, der eine Seite berührt, hat diesen Abstand als Radius und berührt deshalb auch die anderen beiden Seiten: der Inkreis. Durch die Ecken geht der Umkreis, dessen Mittelpunkt auf den Mittelsenkrechten liegt.", "form": "bruecke", "zaehlt": "ja", "r": 8558}, {"l": "umkreis_inkreis", "t": "umkreis_inkreis", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Kind sucht den Mittelpunkt des Inkreises. Zeile 1: Der Inkreis geht durch alle drei Ecken des Dreiecks. Zeile 2: Sein Mittelpunkt hat deshalb zu allen drei Ecken denselben Abstand. Zeile 3: Also zeichnet man die drei Mittelsenkrechten und nimmt ihren Schnittpunkt. In welcher Zeile steckt der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Berührt der Inkreis die Seiten oder geht er durch die Ecken?", "w": "Zeile 1 ist falsch: Der Inkreis berührt die drei Seiten. Durch die Ecken geht der Umkreis. Die Zeilen 2 und 3 folgen richtig aus Zeile 1 und beschreiben dann den Umkreis.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 8559}]$auf$::jsonb),
    (68, 'abbildungen.determinanten2', 411, 18, $auf$[{"l": "det_berechnen", "t": "det_berechnen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Vektoren sind a = (5 | 3) und b = (2 | 7). Das erste Kreuzprodukt (oben links mal unten rechts) ist ①, das zweite (unten links mal oben rechts) ist ②. Die Determinante ist ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [35, 6, 29]}, "h": "Das erste Produkt kommt zuerst, das zweite wird abgezogen.", "w": "5 · 7 = 35 und 3 · 2 = 6. Die Determinante ist 35 − 6 = 29.", "form": "lueckenweg", "zaehlt": "nein", "r": 8412}, {"l": "det_berechnen", "t": "det_berechnen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Für a = (6 | 2) und b = (x | 5) ist die Determinante 26. Wie groß ist x?"}, "o": {"wert": 2}, "h": "Schreibe die Determinante als Gleichung auf.", "w": "6 · 5 − 2 · x = 26, also 30 − 2x = 26 und 2x = 4. Damit ist x = 2.", "form": "umkehren", "zaehlt": "ja", "r": 8413}, {"l": "det_berechnen", "t": "det_berechnen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Kind berechnet die Determinante von a = (6 | 4) und b = (2 | 5). Zeile 1: Über Kreuz malnehmen: 6 · 5 = 30 und 4 · 2 = 8. Zeile 2: Zwischen den beiden Produkten steht ein Plus. Zeile 3: Also ist die Determinante 30 + 8 = 38. In welcher Zeile steckt der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Welches Rechenzeichen steht zwischen den beiden Produkten?", "w": "Zeile 1 stimmt. Zwischen den Produkten steht immer ein Minus: 30 − 8 = 22.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 8414}, {"l": "parallelogramm", "t": "parallelogramm", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Parallelogramm hat A(0 | 0), B(5 | 2) und D(3 | 4). Die Pfeile sind AB = (5 | 2) und AD = (3 | 4). Das erste Kreuzprodukt ist ①, das zweite ②. Die Fläche des Parallelogramms ist ③ FE.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [20, 6, 14]}, "h": "Erst beide Produkte, dann die Differenz.", "w": "5 · 4 = 20 und 2 · 3 = 6. Die Determinante ist 20 − 6 = 14, das Parallelogramm hat 14 FE.", "form": "lueckenweg", "zaehlt": "nein", "r": 8415}, {"l": "parallelogramm", "t": "parallelogramm", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Parallelogramm hat A(1 | 2), B(7 | 2), C(9 | 6) und D(3 | 6). Weg A: Determinante aus AB = (6 | 0) und AD = (2 | 4). Weg B: Grundseite [AB] ist 6 lang, die Höhe ist 4; Grundseite mal Höhe. Wie groß ist die Fläche?"}, "o": {"wert": 24, "einheit": "FE"}, "h": "Beide Wege müssen dieselbe Fläche ergeben.", "w": "Weg A: 6 · 4 − 0 · 2 = 24. Weg B: 6 · 4 = 24. Die Fläche ist 24 FE.", "form": "zwei_wege", "zaehlt": "ja", "r": 8416}, {"l": "parallelogramm", "t": "parallelogramm", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Beet hat die Form eines Parallelogramms mit den Ecken A(0 | 0), B(8 | 0), C(10 | 3) und D(2 | 3). Eine Flächeneinheit entspricht 1 m². Wie viele Quadratmeter hat das Beet?"}, "o": {"wert": 24, "einheit": "m²"}, "h": "Bilde zuerst die Pfeile AB und AD.", "w": "AB = (8 | 0) und AD = (2 | 3). Determinante: 8 · 3 − 0 · 2 = 24. Das Beet hat 24 m².", "form": "anwenden", "zaehlt": "ja", "r": 8417}, {"l": "dreieck", "t": "dreieck", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Dreieck hat A(0 | 0), B(6 | 1) und C(2 | 5), die Pfeile sind AB = (6 | 1) und AC = (2 | 5). Die Determinante ist ①. Das Dreieck hat ② FE. Eine Flächeneinheit sind 4 m²; das Dreieck hat also ③ m².", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [28, 14, 56]}, "h": "Das Dreieck ist das halbe Parallelogramm.", "w": "Die Determinante ist 30 − 2 = 28. Das Dreieck hat 28 : 2 = 14 FE, das sind 14 · 4 m² = 56 m².", "form": "lueckenweg", "zaehlt": "nein", "r": 8418}, {"l": "dreieck", "t": "dreieck", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Im Dreieck ABC sind die Pfeile AB = (4 | 1) und AC = (1 | 3) gegeben. Welche Rechnung gibt die Fläche des Dreiecks?"}, "a": ["(4 · 3 − 1 · 1) : 2", "4 · 3 − 1 · 1", "(4 · 1 − 1 · 3) : 2", "(4 · 3 + 1 · 1) : 2"], "o": {"index": 0}, "h": "Wofür steht die Determinante der beiden Pfeile geometrisch?", "w": "Die Determinante 4 · 3 − 1 · 1 = 11 ist die Fläche des Parallelogramms aus den beiden Pfeilen. Das Dreieck ist die Hälfte: 5,5 FE.", "form": "bruecke", "zaehlt": "ja", "r": 8419}, {"l": "dreieck", "t": "dreieck", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Kind berechnet die Fläche des Dreiecks ABC mit AB = (7 | 2) und AC = (3 | 6). Zeile 1: Die Determinante ist 7 · 3 − 2 · 6 = 9. Zeile 2: Das ist die Fläche des zugehörigen Parallelogramms, also 9 FE. Zeile 3: Das Dreieck ist die Hälfte davon, also 4,5 FE. In welcher Zeile steckt der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Welche Zahlen gehören über Kreuz zusammen?", "w": "Zeile 1 ist falsch: Die Determinante ist 7 · 6 − 2 · 3 = 36 (oben links mal unten rechts). Die Zeilen 2 und 3 folgen richtig aus dem falschen Wert. Richtig wären 36 FE und 18 FE.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 8420}, {"l": "umlaufsinn", "t": "umlaufsinn", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Für ein Dreieck ABC ergibt die Determinante aus AB und AC den Wert −19. Welcher Satz passt dazu?"}, "a": ["Die Ecken laufen im Uhrzeigersinn, die Fläche ist 9,5 FE.", "Die Fläche ist −9,5 FE.", "Die drei Punkte liegen auf einer Geraden.", "Die Fläche ist 19 FE."], "o": {"index": 0}, "h": "Überlege, was ein Minus bei einer Fläche bedeuten kann.", "w": "Das Minus zeigt nur die Reihenfolge der Ecken. Die Fläche ist der halbe Betrag: 19 : 2 = 9,5 FE.", "form": "bruecke", "zaehlt": "ja", "r": 8421}, {"l": "umlaufsinn", "t": "umlaufsinn", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Für ein Dreieck ABC ergibt die Determinante aus AB und AC den Wert 18. Du willst, dass sich nur das Vorzeichen ändert und der Betrag gleich bleibt. Was änderst du?"}, "a": ["zwei Ecken in der Reihenfolge vertauschen, zum Beispiel B und C", "alle Koordinaten mit −1 malnehmen", "die Determinante durch 2 teilen", "die Koordinaten von A um 1 verschieben"], "o": {"index": 0}, "h": "Was ändert sich am Umlaufsinn, wenn du zwei Ecken tauschst?", "w": "Tauscht man B und C, vertauschen sich die beiden Pfeile, und die Determinante wechselt das Vorzeichen: −18. Alle Koordinaten mit −1 zu nehmen dreht die Figur um 180°, die Determinante bleibt 18. Durch 2 teilen halbiert den Betrag, und eine Verschiebung von A ändert die Pfeile und meist den Betrag.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 8422}, {"l": "umlaufsinn", "t": "umlaufsinn", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Kind rechnet mit AB = (2 | 5) und AC = (6 | 1). Zeile 1: Die Determinante ist 2 · 1 − 5 · 6 = −28. Zeile 2: Das Minus zeigt, dass A, B und C im Uhrzeigersinn liegen. Zeile 3: Die Fläche des Dreiecks ist deshalb −14 FE. In welcher Zeile steckt der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Kann eine Fläche negativ sein?", "w": "Zeile 1 und 2 stimmen. Flächen sind nie negativ: man nimmt den Betrag, also 28 : 2 = 14 FE.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 8423}, {"l": "viereck", "t": "viereck", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Viereck hat A(0 | 0), B(6 | 2), C(5 | 6) und D(1 | 4). Die Diagonale AC teilt es in die Dreiecke ABC und ACD. Die Determinante für ABC (aus AB und AC) ist ①, die für ACD (aus AC und AD) ist ②. Die Fläche des Vierecks ist ③ FE.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [26, 14, 20]}, "h": "Beide Determinanten werden addiert, dann wird halbiert.", "w": "Für ABC: 36 − 10 = 26. Für ACD: 20 − 6 = 14. Zusammen 40, halbiert 20 FE.", "form": "lueckenweg", "zaehlt": "nein", "r": 8424}, {"l": "viereck", "t": "viereck", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Viereck hat A(0 | 0), B(4 | 0), C(4 | 3) und D(0 | 3). Weg A: mit der Diagonale AC in zwei Dreiecke zerlegen, beide Determinanten addieren und halbieren. Weg B: es ist ein Rechteck, also Länge mal Breite. Wie groß ist die Fläche?"}, "o": {"wert": 12, "einheit": "FE"}, "h": "Beide Wege müssen dieselbe Fläche ergeben.", "w": "Weg A: Dreieck ABC gibt 12, Dreieck ACD gibt 12, zusammen 24, halbiert 12. Weg B: 4 · 3 = 12. Die Fläche ist 12 FE.", "form": "zwei_wege", "zaehlt": "ja", "r": 8425}, {"l": "viereck", "t": "viereck", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Ein Grundstück hat die Ecken A(0 | 0), B(10 | 0), C(10 | 6) und D(0 | 4). Eine Flächeneinheit entspricht 1 m². Wie viele Quadratmeter hat das Grundstück?"}, "o": {"wert": 50, "einheit": "m²"}, "h": "Teile das Viereck mit der Diagonale AC in zwei Dreiecke.", "w": "Dreieck ABC: 10 · 6 − 0 · 10 = 60. Dreieck ACD: 10 · 4 − 6 · 0 = 40. Zusammen 100, halbiert 50 m². Probe als Trapez: (4 + 6) : 2 · 10 = 50.", "form": "anwenden", "zaehlt": "ja", "r": 8426}, {"l": "vieleck", "t": "vieleck", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Ein Fünfeck ABCDE soll von A aus in Dreiecke zerlegt werden. Welche Determinanten rechnest du?"}, "a": ["AB mit AC, AC mit AD, AD mit AE", "AB mit AD, AD mit AE", "AB mit AC, AB mit AD, AB mit AE", "AB mit AC, AC mit AE"], "o": {"index": 0}, "h": "Zeichne ein Fünfeck und die Diagonalen von A aus.", "w": "Von A aus entstehen die Dreiecke ABC, ACD und ADE. Dazu nimmt man immer zwei benachbarte Pfeile: AB mit AC, AC mit AD, AD mit AE.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 8427}, {"l": "vieleck", "t": "vieleck", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Ein konvexes Fünfeck, dessen Ecken gegen den Uhrzeigersinn benannt sind, hat die Fläche 27 FE. Von A aus wird es in drei Dreiecke zerlegt. Zwei der drei Determinanten sind 12 und 19. Wie groß ist die dritte?"}, "o": {"wert": 23}, "h": "Wie hängen die drei Dreiecksflächen mit der Fläche des Fünfecks zusammen?", "w": "Die Summe der Determinanten ist 2 · 27 = 54. Bekannt sind 12 + 19 = 31. Die dritte ist 54 − 31 = 23.", "form": "umkehren", "zaehlt": "ja", "r": 8428}, {"l": "vieleck", "t": "vieleck", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Grundstück hat die Form eines Fünfecks mit A(0 | 0), B(8 | 0), C(10 | 5), D(4 | 8) und E(0 | 5). Eine Flächeneinheit entspricht 1 m². Wie viele Quadratmeter hat das Grundstück?"}, "o": {"wert": 60, "einheit": "m²"}, "h": "Von A aus zerlegen und immer zwei benachbarte Pfeile nehmen.", "w": "AB mit AC: 40. AC mit AD: 60. AD mit AE: 20. Zusammen 120, halbiert 60 m².", "form": "anwenden", "zaehlt": "ja", "r": 8429}]$auf$::jsonb),
    (70, 'daten.stichproben', 402, 15, $auf$[{"l": "begriffe", "t": "begriffe", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Eine Schule hat 480 Kinder. Für eine Umfrage wird jedes achte Kind befragt. Der Stichprobenumfang ist n = ①. Nicht befragt werden ② Kinder.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [60, 420]}, "h": "Jedes achte Kind: Wie oft passt 8 in die Gesamtzahl?", "w": "480 : 8 = 60 befragte Kinder, das ist die Stichprobe. Die Grundgesamtheit sind alle 480 Kinder; 480 − 60 = 420 werden nicht befragt.", "form": "lueckenweg", "zaehlt": "nein", "r": 8403}, {"l": "begriffe", "t": "begriffe", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Bei einer Umfrage ist der Stichprobenumfang n = 45. Das ist genau ein Fünftel der Grundgesamtheit. Wie groß ist die Grundgesamtheit?"}, "o": {"wert": 225, "einheit": "Personen"}, "h": "Wie viele Stichproben dieser Größe passen in die ganze Gruppe?", "w": "45 · 5 = 225. Die Grundgesamtheit umfasst 225 Personen, befragt wurden 45 davon.", "form": "umkehren", "zaehlt": "ja", "r": 8404}, {"l": "begriffe", "t": "begriffe", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Ein Bericht schreibt kurz: n = 60 und N = 480 (n ist der Stichprobenumfang, N die Größe der Grundgesamtheit). Welcher Satz sagt dasselbe?"}, "a": ["Aus 480 Personen wurden 60 ausgewählt und befragt.", "Aus 60 Personen wurden 480 ausgewählt und befragt.", "Es wurden 60 % von 480 Personen befragt.", "Alle 480 Personen wurden befragt."], "o": {"index": 0}, "h": "Lies nach, was n und was N bedeutet.", "w": "N = 480 ist die Grundgesamtheit, n = 60 die Stichprobe: aus 480 Personen wurden 60 befragt. 60 % von 480 wären 288 Personen, und bei einer Befragung aller 480 wäre n = 480.", "form": "bruecke", "zaehlt": "ja", "r": 8405}, {"l": "hochrechnen", "t": "hochrechnen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "In einer Stichprobe von 60 Kindern fahren 24 mit dem Rad. Auf 100 Kinder gerechnet sind das ① Prozent. Bei 850 Kindern insgesamt schätzt man ② Radfahrer.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [40, 340]}, "h": "Erst den Anteil in Prozent, dann auf die große Gruppe anwenden.", "w": "24 : 60 = 0,4, also 40 %. 40 % von 850 sind 340 Kinder. Das Ergebnis ist eine Schätzung.", "form": "lueckenweg", "zaehlt": "nein", "r": 8406}, {"l": "hochrechnen", "t": "hochrechnen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "In einer Stichprobe von 50 zufällig ausgewählten Personen sind 12 Linkshänder, die Grundgesamtheit hat 900 Personen. Weg A: den Anteil 12 : 50 = 0,24 bilden und mit 900 malnehmen. Weg B: 900 : 50 = 18 rechnen, die Grundgesamtheit ist also 18-mal so groß, dann 12 · 18. Wie viele Linkshänder schätzt man?"}, "o": {"wert": 216, "einheit": "Personen"}, "h": "Beide Wege müssen dieselbe Schätzung ergeben.", "w": "Weg A: 0,24 · 900 = 216. Weg B: 900 : 50 = 18 und 12 · 18 = 216. Man schätzt etwa 216 Linkshänder.", "form": "zwei_wege", "zaehlt": "ja", "r": 8407}, {"l": "hochrechnen", "t": "hochrechnen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Gemeinde mit 7 200 Einwohnern befragt 120 zufällig ausgewählte Personen. 45 von ihnen nutzen den Bus. Wie viele Busnutzer schätzt man in der ganzen Gemeinde?"}, "o": {"wert": 2700, "einheit": "Einwohner"}, "h": "Erst den Anteil der Stichprobe, dann auf alle Einwohner hochrechnen.", "w": "45 : 120 = 0,375, also 37,5 %. 0,375 · 7 200 = 2 700 Einwohner. Das ist eine Schätzung.", "form": "anwenden", "zaehlt": "ja", "r": 8408}, {"l": "repraesentativ", "t": "repraesentativ", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Eine Schule hat 1 000 Kinder: 520 Mädchen und 480 Jungen. In einer Stichprobe von 100 Kindern sind 70 Mädchen und 30 Jungen. Was legt der Vergleich der beiden Verteilungen nahe?"}, "a": ["Die Stichprobe bildet die Schule nicht gut ab, sie ist vermutlich nicht repräsentativ.", "Die Stichprobe ist sicher repräsentativ, weil mehr Mädchen als Jungen dabei sind.", "Die Stichprobe ist repräsentativ, weil 100 eine runde Zahl ist.", "Die Schule hat 70 Mädchen."], "o": {"index": 0}, "h": "Berechne in beiden Fällen den Anteil der Mädchen.", "w": "In der Schule sind 52 % Mädchen, in der Stichprobe 70 %. Ein so großer Unterschied spricht dafür, dass die Auswahl einseitig war. Eine runde Zahl macht eine Stichprobe nicht repräsentativ.", "form": "bruecke", "zaehlt": "ja", "r": 8409}, {"l": "repraesentativ", "t": "repraesentativ", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Du willst wissen, wie viele Kinder einer Schule ein Instrument spielen. Welches Vorgehen gibt die beste Stichprobe?"}, "a": ["in jeder Klasse einige Kinder zufällig auswählen", "alle Kinder des Schulorchesters befragen", "nur die Kinder befragen, die freiwillig antworten wollen", "die ersten 20 Kinder vor dem Musikraum befragen"], "o": {"index": 0}, "h": "Woher kommt eine einseitige Auswahl?", "w": "Nur die zufällige Auswahl über alle Klassen ist repräsentativ. Orchester und Musikraum liefern zu viele musizierende Kinder, und Freiwillige haben meist eine starke Meinung.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 8410}, {"l": "repraesentativ", "t": "repraesentativ", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Kind beurteilt eine Umfrage, bei der 500 Mitglieder eines Sportvereins zu ihrer Freizeit befragt wurden. Zeile 1: Eine Stichprobe ist repräsentativ, wenn sie nur groß genug ist. Zeile 2: 500 Befragte sind eine große Stichprobe. Zeile 3: Also ist diese Umfrage repräsentativ für alle Menschen der Stadt. In welcher Zeile steckt der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Genügt eine große Zahl allein?", "w": "Zeile 1 ist falsch: Repräsentativ heißt zufällig ausgewählt und groß genug. Vereinsmitglieder treiben fast alle Sport, die Auswahl ist einseitig. Die Zeilen 2 und 3 folgen richtig aus Zeile 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 8411}, {"l": "fehlerquellen", "t": "fehlerquellen", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Eine Frage lautet: „Finden Sie nicht auch, dass der Pausenhof dringend erneuert werden muss?“ Wie sollte man stattdessen fragen?"}, "a": ["„Soll der Pausenhof erneuert werden?“", "„Warum muss der Pausenhof erneuert werden?“", "„Sind Sie gegen eine Erneuerung, obwohl alle dafür sind?“", "„Wie dringend ist die Erneuerung des Pausenhofs?“"], "o": {"index": 0}, "h": "Welche Frage setzt nichts voraus?", "w": "Neutral ist die Frage ohne Vorannahme: „Soll der Pausenhof erneuert werden?“ Die anderen Formulierungen setzen die Erneuerung schon voraus oder drängen zu einer Antwort.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 8412}, {"l": "fehlerquellen", "t": "fehlerquellen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Bei einer Online-Abstimmung stimmen 8 400 von 12 000 Teilnehmenden mit Ja. Wie viel Prozent der Teilnehmenden sind das?"}, "o": {"wert": 70, "einheit": "%"}, "h": "Anteil bilden und mit 100 malnehmen.", "w": "8 400 : 12 000 = 0,7, also 70 %. Aussagekräftig ist die Zahl trotzdem nicht: es haben nur Freiwillige abgestimmt, und die haben meist eine starke Meinung.", "form": "anwenden", "zaehlt": "ja", "r": 8413}, {"l": "fehlerquellen", "t": "fehlerquellen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Kind prüft eine Umfrage. Zeile 1: Die Frage war neutral gestellt. Zeile 2: Angeschrieben wurden 300 zufällig ausgewählte Personen. Zeile 3: Geantwortet haben nur die 40 Personen, die Lust dazu hatten – das Ergebnis ist deshalb genauso gut. In welcher Zeile steckt der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Wer antwortet am Ende wirklich?", "w": "Zeile 1 und 2 stimmen. Antworten am Ende nur Freiwillige, ist die Auswahl wieder einseitig – auch wenn vorher zufällig ausgewählt wurde.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 8414}, {"l": "aussagen", "t": "aussagen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "In Stichprobe A mögen 6 von 10 Kindern das Essen, in Stichprobe B 230 von 500. Weg A: beide Anteile in Prozent umrechnen und voneinander abziehen. Weg B: 6 von 10 als 300 von 500 schreiben und mit 230 vergleichen. Um wie viele Prozentpunkte liegt A über B?"}, "o": {"wert": 14, "einheit": "Prozentpunkte"}, "h": "Beide Wege müssen denselben Unterschied zeigen.", "w": "A: 6 : 10 = 60 %. B: 230 : 500 = 46 %. 60 − 46 = 14 Prozentpunkte. Weg B: 300 gegen 230 von 500 – derselbe Unterschied.", "form": "zwei_wege", "zaehlt": "ja", "r": 8415}, {"l": "aussagen", "t": "aussagen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Stichprobe von 200 Haushalten ergibt 30 % mit Haustier. Die Gemeinde hat 4 500 Haushalte, die Stichprobe gilt als repräsentativ. Wie viele Haushalte mit Haustier schätzt man?"}, "o": {"wert": 1350, "einheit": "Haushalte"}, "h": "Der Anteil der Stichprobe wird auf alle übertragen.", "w": "30 % von 4 500 sind 1 350 Haushalte. Weil der Wert aus nur 200 Haushalten geschätzt ist, kann der wahre Wert davon abweichen.", "form": "anwenden", "zaehlt": "ja", "r": 8416}, {"l": "aussagen", "t": "aussagen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "In einer Stichprobe haben 40 % ein Haustier. Hochgerechnet auf die Grundgesamtheit sind das 360 Personen mit Haustier. Wie groß ist die Grundgesamtheit?"}, "o": {"wert": 900, "einheit": "Personen"}, "h": "40 % entsprechen 360 Personen; gesucht sind 100 %.", "w": "1 % sind 360 : 40 = 9 Personen. 100 % sind 9 · 100 = 900 Personen.", "form": "umkehren", "zaehlt": "ja", "r": 8417}]$auf$::jsonb),
    (310, 'raum.schraegbilder_teil2', 582, 12, $auf$[{"l": "koordinaten", "t": "koordinaten", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Quader liegt mit A im Ursprung, seine Kanten verlaufen auf den Achsen. Die Ecke G(5 | 3 | 4) liegt gegenüber von A. Die Grundfläche des Quaders hat ① FE. Das Volumen des Quaders ist ② VE.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [15, 60]}, "h": "Welche Koordinaten gehören zur Grundfläche?", "w": "Die Grundfläche liegt in der x-y-Ebene: 5 · 3 = 15 FE. Mit der Höhe 4 (z-Koordinate) ist das Volumen 15 · 4 = 60 VE.", "form": "lueckenweg", "zaehlt": "nein", "r": 8583}, {"l": "koordinaten", "t": "koordinaten", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "In einem Quader mit A im Ursprung, dessen Kanten auf den Achsen verlaufen, ist G(7 | 4 | 3) die Ecke gegenüber von A. Wie viele Flächeneinheiten hat die Grundfläche?"}, "o": {"wert": 28, "einheit": "FE"}, "h": "Welche Koordinaten gehören zur Grundfläche?", "w": "Der Quader ist 7 lang und 4 breit; die Höhe 3 gehört nicht zur Grundfläche. Grundfläche: 7 · 4 = 28 FE.", "form": "umkehren", "zaehlt": "ja", "r": 8584}, {"l": "koordinaten", "t": "koordinaten", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Quader liegt mit A im Ursprung, ist 5 lang, 3 breit und 2 hoch; B liegt auf der x-Achse, D auf der y-Achse. Ein Kind sagt: Zeile 1: E liegt senkrecht über A, also E(0 | 0 | 2). Zeile 2: D liegt auf der y-Achse, also D(3 | 0 | 0). Zeile 3: H liegt senkrecht über D, also H(3 | 0 | 2). In welcher Zeile steckt der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Auf welcher Achse hat eine Ecke nur einen Wert ungleich null?", "w": "Zeile 1 stimmt. In Zeile 2 sind x und y vertauscht: Auf der y-Achse sind x und z null, D(0 | 3 | 0). Zeile 3 folgt richtig aus Zeile 2 (2 höher), übernimmt aber den Fehler. Richtig wäre H(0 | 3 | 2).", "form": "fehler_detektiv", "zaehlt": "ja", "r": 8585}, {"l": "rotation", "t": "rotation", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Ein Rechteck mit den Seiten 4 cm und 7 cm dreht sich um die 7-cm-Seite. Welcher Körper entsteht, und mit welchen Maßen?"}, "a": ["ein Zylinder mit r = 4 cm und h = 7 cm", "ein Zylinder mit r = 7 cm und h = 4 cm", "ein Kegel mit r = 4 cm und h = 7 cm", "eine Kugel mit r = 7 cm"], "o": {"index": 0}, "h": "Stell dir vor, wie sich das Rechteck dreht: Welche Seite bleibt an Ort und Stelle?", "w": "Die 7-cm-Seite liegt auf der Achse und wird die Höhe. Die 4-cm-Seite dreht sich im Kreis und wird der Radius: ein Zylinder mit r = 4 cm und h = 7 cm.", "form": "bruecke", "zaehlt": "ja", "r": 8586}, {"l": "rotation", "t": "rotation", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Du sollst eine Kugel durch Drehen erzeugen. Welche Fläche nimmst du, und um welche Achse?"}, "a": ["einen Halbkreis um seinen Durchmesser", "einen Viertelkreis um eine seiner geraden Kanten", "ein Rechteck um eine Seite", "ein rechtwinkliges Dreieck um eine Kathete"], "o": {"index": 0}, "h": "Welche Umrisslinie gehört zur Kugel?", "w": "Ein Halbkreis, der um seinen Durchmesser gedreht wird, ergibt die Kugel. Das Rechteck gibt einen Zylinder, das rechtwinklige Dreieck einen Kegel, der Viertelkreis nur eine halbe Kugel.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 8587}, {"l": "rotation", "t": "rotation", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "In einer Werkstatt entsteht ein Kegel, indem ein Pappdreieck mit einem rechten Winkel und den Katheten 5 cm und 12 cm um die 12-cm-Kathete gedreht wird. Wie groß ist der Durchmesser des Kegels?"}, "o": {"wert": 10, "einheit": "cm"}, "h": "Welche Kathete bleibt beim Drehen auf der Achse?", "w": "Die 12-cm-Kathete liegt auf der Achse und wird die Höhe, die 5-cm-Kathete wird der Radius. Der Durchmesser ist 2 · 5 cm = 10 cm.", "form": "anwenden", "zaehlt": "ja", "r": 8588}, {"l": "axialschnitt", "t": "axialschnitt", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Zylinder hat r = 4 cm und h = 9 cm. Der Axialschnitt geht durch die Achse. Das Schnittrechteck ist ① cm breit. Seine Fläche ist ② cm². Sein Umfang ist ③ cm.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [8, 72, 34]}, "h": "Welche Strecke im Kreis geht durch den Mittelpunkt?", "w": "Der Schnitt erfasst den ganzen Durchmesser: 2 · 4 cm = 8 cm. Fläche: 8 · 9 = 72 cm². Umfang: 2 · (8 + 9) = 34 cm.", "form": "lueckenweg", "zaehlt": "nein", "r": 8589}, {"l": "axialschnitt", "t": "axialschnitt", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Zylinder hat den Durchmesser 10 cm und die Höhe 6 cm; er wird genau durch die Achse geschnitten. Weg A: Durchmesser mal Höhe. Weg B: den Schnitt in 10 Streifen von je 1 cm Breite zerlegen und die Flächen der Streifen addieren. Wie groß ist die Fläche des Axialschnitts?"}, "o": {"wert": 60, "einheit": "cm²"}, "h": "Beide Wege müssen dieselbe Fläche ergeben.", "w": "Weg A: 10 · 6 = 60 cm². Weg B: Ein Streifen hat 1 · 6 = 6 cm², zehn Streifen haben 60 cm². Der Axialschnitt hat 60 cm².", "form": "zwei_wege", "zaehlt": "ja", "r": 8590}, {"l": "axialschnitt", "t": "axialschnitt", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Dose ist ein Zylinder mit r = 3 cm und h = 11 cm. Sie wird längs genau durch die Achse aufgeschnitten. Wie groß ist eine der beiden entstehenden Schnittflächen?"}, "o": {"wert": 66, "einheit": "cm²"}, "h": "Wie breit ist der Schnitt, wenn er durch die Achse geht?", "w": "Die Breite ist 2 · 3 cm = 6 cm, die Höhe 11 cm. Jede Schnittfläche ist 6 · 11 = 66 cm².", "form": "anwenden", "zaehlt": "ja", "r": 8591}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Ein Körper hat 9 Symmetrieebenen. Welcher Körper ist das?"}, "a": ["ein Würfel", "ein Quader mit drei verschiedenen Kantenlängen", "eine quadratische Säule, die kein Würfel ist", "eine gerade Pyramide über einem Quadrat"], "o": {"index": 0}, "h": "Zähle die Symmetrieebenen jedes genannten Körpers.", "w": "Der Würfel hat 9 Symmetrieebenen: 3 mittige und 6 diagonale. Der Quader hat 3, die quadratische Säule 5, die gerade Pyramide über einem Quadrat 4.", "form": "bruecke", "zaehlt": "ja", "r": 8592}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Eine gerade Pyramide über einem regelmäßigen n-Eck hat 7 Symmetrieebenen. Wie viele Ecken hat diese Pyramide?"}, "o": {"wert": 8, "einheit": "Ecken"}, "h": "Wie viele Symmetrieebenen hat eine gerade Pyramide über einem Dreieck, wie viele über einem Quadrat?", "w": "7 Ebenen heißen n = 7, die Grundfläche ist ein Siebeneck. Ecken: 7 + 1 = 8.", "form": "umkehren", "zaehlt": "ja", "r": 8593}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein gerades Prisma hat ein regelmäßiges Sechseck als Grundfläche. Weg A: die Regel n + 1 für gerade Prismen über regelmäßigen n-Ecken anwenden. Weg B: die Symmetrieachsen des Sechsecks zählen (durch gegenüberliegende Ecken, durch gegenüberliegende Seitenmitten) und die mittige waagerechte Ebene dazunehmen. Wie viele Symmetrieebenen hat das Prisma?"}, "o": {"wert": 7, "einheit": "Ebenen"}, "h": "Beide Wege müssen dieselbe Zahl ergeben.", "w": "Weg A: n + 1 = 6 + 1 = 7. Weg B: 3 Achsen durch gegenüberliegende Ecken und 3 durch gegenüberliegende Seitenmitten geben 6 senkrechte Ebenen, dazu 1 waagerechte: 7.", "form": "zwei_wege", "zaehlt": "ja", "r": 8594}]$auf$::jsonb)
  ) x(id, schluessel, max_r, soll, aufgaben) loop
    if not exists (select 1 from schule.einheit ei join schule.thema th on th.id = ei.thema_id where ei.id = e.id and th.schluessel = e.schluessel) then
      fehler := fehler || ('Einheit ' || e.id || ' ist nicht ' || e.schluessel)::text; continue; end if;
    if (select coalesce(max(reihenfolge), 0) from schule.aufgabe where einheit_id = e.id and pool = 'uebung' and reihenfolge <= e.max_r) <> e.max_r then
      fehler := fehler || ('Einheit ' || e.id || ': Bestand hat sich seit dem Lesen geändert')::text; continue; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.pool = 'uebung' and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x)) then
      fehler := fehler || ('Einheit ' || e.id || ': Reihenfolge-Nummern des Pakets sind schon belegt (Paket schon eingespielt?)')::text; continue; end if;
    if exists (select 1 from jsonb_array_elements(e.aufgaben) x where not exists (select 1 from schule.einheit ei, jsonb_array_elements(ei.inhalt->'etappen') et where ei.id = e.id and et->>'lernziel' = x->>'l')) then
      fehler := fehler || ('Einheit ' || e.id || ': Lernziel unbekannt')::text; continue; end if;
    select count(*) into vorher from schule.aufgabe where einheit_id = e.id;
    n := schule.aufgaben_einfuegen(e.id, e.aufgaben);
    if n <> e.soll or (select count(*) from schule.aufgabe where einheit_id = e.id) <> vorher + e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': ' || n || ' statt ' || e.soll || ' eingefügt')::text; end if;
    if (select count(*) from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung' and a.form is not null and a.zaehlt is not null) <> e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': form/zaehlt nicht übernommen')::text; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung'
               and not coalesce((schule.antwort_bewerten(a, case a.antworttyp when 'zahl' then jsonb_build_object('wert', '0') else '{}'::jsonb end)->>'format_ok') is not null, false)) then
      fehler := fehler || ('Einheit ' || e.id || ': eine neue Aufgabe lässt sich nicht bewerten')::text; end if;
    gesamt := gesamt + n;
  end loop;
  if gesamt <> 156 then fehler := fehler || ('zusammen ' || gesamt || ' statt 156')::text; end if;
  if array_length(fehler, 1) > 0 then raise exception 'Vorrats-Aufgaben ABBRUCH, alles zurückgerollt: %', array_to_string(fehler, ' | '); end if;
end $einspielen$;
select einheit_id, count(*) filter (where pool = 'uebung') as uebungen, count(*) filter (where form is not null) as mit_form from schule.aufgabe where einheit_id in (2, 14, 30, 35, 42, 56, 58, 68, 70, 310) group by 1 order by 1;
